                        # renumber colors to be consecutive
                        mapping = {}
                        next_c = 0
                        for col in sorted(set(new_colors)):
                            mapping[col] = next_c
                            next_c += 1
                        final_colors = [mapping[c] for c in new_colors]
                        return final_colors
        # try Kempe chains: for each v in target color, for each c < target, try swap
        for v in vertices:
            for c in range(target):
                # try to swap colors target and c in the component containing v
                swapped = kempe_swap(colors, v, target, c)
                # after swap, check if v is now color c (meaning it was in the swapped component)
                if swapped[v] == c:
                    # check if target color is still used anywhere
                    if target not in swapped:
                        mapping = {}
                        next_c = 0
                        for col in sorted(set(swapped)):
                            mapping[col] = next_c
                            next_c += 1
                        final_colors = [mapping[col] for col in swapped]
                        return final_colors
        # cannot reduce
        return colors

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass
    # Fallback: greedy by original order
    try:
        c4 = greedy_color(list(range(n)))
        if is_valid(c4):
            candidates.append(c4)
    except:
        pass

    # Select best candidate (fewest colors)
    best = None
    best_k = float('inf')
    for col in candidates:
        k = num_colors(col)
        if k < best_k:
            best_k = k
            best = col
    if best is None:
        best = [0] * n  # should not happen

    # Iteratively apply color reduction
    current = best
    while True:
        reduced = reduce_colors(current)
        if num_colors(reduced) >= num_colors(current):
            break
        current = reduced

    # Ensure colors are consecutive starting from 0
    used_colors = sorted(set(current))
    mapping = {col: i for i, col in enumerate(used_colors)}
    final = [mapping[c] for c in current]
    return final

