def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Convert to adjacency list and bitmask
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    bit_adj = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            bit_adj[u] |= (1 << v)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # DSATUR
    def dsatur():
        color = [-1] * n
        sat = [0] * n
        uncolored = set(range(n))
        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (sat[x], sum(1 for y in adj_list[x] if y in uncolored)))
            # Assign smallest available color
            used = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    used |= (1 << color[u])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat[u] += 1
        return color

    # RLF
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in adj_list[x] if y in uncolored))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set
            U = {u for u in uncolored if u != v and not (bit_adj[v] & (1 << u))}
            # W: vertices adjacent to at least one in independent_set
            W = {u for u in uncolored if u != v and (bit_adj[v] & (1 << u))}
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u_star = max(U, key=lambda x: (sum(1 for y in adj_list[x] if y in W), -sum(1 for y in adj_list[x] if y in U)))
                independent_set.add(u_star)
                U.remove(u_star)
                # Move neighbors of u_star from U to W
                for y in adj_list[u_star]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # Assign color c to independent_set
            for vtx in independent_set:
                color[vtx] = c
                uncolored.remove(vtx)
            c += 1
        return color

    # Smallest-Last ordering greedy
    def smallest_last():
        # Compute degeneracy ordering
        order = []
        degrees = [len(adj_list[i]) for i in range(n)]
        remaining = set(range(n))
        while remaining:
            v = min(remaining, key=lambda x: degrees[x])
            order.append(v)
            remaining.remove(v)
            for u in adj_list[v]:
                if u in remaining:
                    degrees[u] -= 1
        # Color in reverse order
        return greedy_color(reversed(order))

    # Generate initial candidates
    candidates = []
    candidates.append(dsatur())
    candidates.append(rlf())
    candidates.append(smallest_last())

    # Select best initial coloring (fewest colors)
    best_color = min(candidates, key=lambda col: max(col) + 1 if col else 0)
    k = max(best_color) + 1 if best_color else 0

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        nonlocal k
        changed = True
        while changed and k > 1:
            changed = False
            # Find smallest color class
            classes = [[] for _ in range(k)]
            for v in range(n):
                classes[coloring[v]].append(v)
            # Try to eliminate color k-1
            target_color = k - 1
            if not classes[target_color]:
                # Already empty, compact
                for v in range(n):
                    if coloring[v] > target_color:
                        coloring[v] -= 1
                k -= 1
                changed = True
                continue
            # Try to recolor each vertex in target class
            for v in classes[target_color]:
                # Try direct reassignment to a lower color
                used = 0
                for u in adj_list[v]:
                    if coloring[u] != -1:
                        used |= (1 << coloring[u])
                for c in range(target_color):
                    if not (used & (1 << c)):
                        coloring[v] = c
                        changed = True
                        break
                if changed:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # If v already has color c after possible direct reassignment, skip
                    if coloring[v] == c:
                        continue
                    # Find the Kempe chain component of v in colors {target_color, c}
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == target_color or coloring[node] == c:
                            component.add(node)
                            for nb in adj_list[node]:
                                if nb not in visited and (coloring[nb] == target_color or coloring[nb] == c):
                                    stack.append(nb)
                    # Check if any neighbor of v in the component has color c (would cause conflict if swapped)
                    conflict = False
                    for node in component:
                        for nb in adj_list[node]:
                            if coloring[nb] == c and nb not in component:
                                conflict = True
                                break
                        if conflict:
                            break
                    if not conflict:
                        # Swap colors in the component
                        for node in component:
                            if coloring[node] == target_color:
                                coloring[node] = c
                            else:
                                coloring[node] = target_color
                        changed = True
                        break
                if changed:
                    break
            if not changed:
                # Could not eliminate target color, try to compact if possible
                # Check if any color class is empty
                for c in range(k):
                    if not classes[c]:
                        # Shift down higher colors
                        for v in range(n):
                            if coloring[v] > c:
                                coloring[v] -= 1
                        k -= 1
                        changed = True
                        break
        return coloring

    best_color = kempe_reduce(best_color[:])

    # Final validation and compacting
    # Ensure valid coloring
    for u in range(n):
        for v in adj_list[u]:
            if u < v and best_color[u] == best_color[v]:
                # Fallback to greedy with degree order if invalid (should not happen)
                order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
                best_color = greedy_color(order)
                break
        else:
            continue
        break

    # Compact colors to 0..k-1
    unique_colors = {}
    next_color = 0
    for i in range(n):
        c = best_color[i]
        if c not in unique_colors:
            unique_colors[c] = next_color
            next_color += 1
        best_color[i] = unique_colors[c]

    return best_color

