def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    # Detect adjacency matrix
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        all_binary = True
        for i in range(n):
            for j in range(n):
                val = adj[i][j]
                if val != 0 and val != 1:
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True
    # Build adjacency list and bit masks
    if is_matrix:
        adj_list = []
        bit_adj = [0] * n
        for i in range(n):
            neighbors = []
            mask = 0
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors.append(j)
                    mask |= (1 << j)
            adj_list.append(neighbors)
            bit_adj[i] = mask
    else:
        adj_list = adj
        bit_adj = [0] * n
        for i in range(n):
            mask = 0
            for nb in adj_list[i]:
                mask |= (1 << nb)
            bit_adj[i] = mask

    # Helper: count bits in mask
    def popcount(x: int) -> int:
        return x.bit_count()

    # Helper: check if coloring is valid
    def is_valid_coloring(colors: list[int]) -> bool:
        for u in range(n):
            for v in adj_list[u]:
                if u < v and colors[u] == colors[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(colors: list[int]) -> int:
        if not colors:
            return 0
        return max(colors) + 1

    # Helper: greedy coloring with given order
    def greedy_color(order: list[int]) -> list[int]:
        colors = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                c = colors[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors

    # Heuristic 1: DSATUR with bitmask optimization
    def dsatur() -> list[int]:
        colors = [-1] * n
        # saturation mask per vertex: bits of colors used by colored neighbors
        sat_mask = [0] * n
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation degree, tie-break by degree in uncolored subgraph, then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                sat = popcount(sat_mask[v])
                # degree in uncolored subgraph
                deg = popcount(bit_adj[v] & sum((1 << u) for u in uncolored))
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and random.random() < 0.5):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v
            # assign smallest available color
            used = sat_mask[v]
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
            uncolored.remove(v)
            # update saturation masks of uncolored neighbors
            for u in adj_list[v]:
                if u in uncolored:
                    sat_mask[u] |= (1 << c)
        return colors

    # Heuristic 2: RLF (Recursive Largest First) independent set extraction
    def rlf() -> list[int]:
        colors = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # independent set for this color
            S = set()
            # choose vertex with max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: popcount(bit_adj[x] & sum((1 << u) for u in uncolored)))
            S.add(v)
            # partition remaining uncolored into U (not adjacent to S) and W (adjacent to S)
            U = uncolored - {v}
            W = set()
            for u in list(U):
                if any((bit_adj[u] & (1 << w)) for w in S):
                    U.remove(u)
                    W.add(u)
            # greedily add to S from U
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                for u in U:
                    score = popcount(bit_adj[u] & sum((1 << w) for w in W))
                    degU = popcount(bit_adj[u] & sum((1 << w) for w in U))
                    if score > best_score or (score == best_score and degU < best_degU):
                        best_score = score
                        best_degU = degU
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for w in list(U):
                    if bit_adj[u] & (1 << w):
                        U.remove(w)
                        W.add(w)
            # assign color to all in S
            for v in S:
                colors[v] = color
            uncolored -= S
            color += 1
        return colors

    # Heuristic 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last() -> list[int]:
        # compute degeneracy ordering
        remaining = set(range(n))
        order = []
        degrees = [popcount(bit_adj[v]) for v in range(n)]
        # we need dynamic degrees in the induced subgraph
        # simple O(n^2) method: repeatedly remove min degree vertex
        temp_adj = [set(adj_list[v]) for v in range(n)]
        remaining_set = set(range(n))
        while remaining_set:
            # find vertex with min degree in remaining_set
            min_v = None
            min_deg = float('inf')
            for v in remaining_set:
                deg = len(temp_adj[v] & remaining_set)
                if deg < min_deg:
                    min_deg = deg
                    min_v = v
            order.append(min_v)
            remaining_set.remove(min_v)
            # remove min_v from neighbors' adjacency
            for u in temp_adj[min_v]:
                if u in remaining_set:
                    temp_adj[u].discard(min_v)
        # color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    try:
        c1 = dsatur()
        if is_valid_coloring(c1):
            candidates.append(c1)
    except Exception:
        pass
    try:
        c2 = rlf()
        if is_valid_coloring(c2):
            candidates.append(c2)
    except Exception:
        pass
    try:
        c3 = smallest_last()
        if is_valid_coloring(c3):
            candidates.append(c3)
    except Exception:
        pass
    # Fallback: greedy by natural order
    try:
        c4 = greedy_color(list(range(n)))
        if is_valid_coloring(c4):
            candidates.append(c4)
    except Exception:
        pass

    if not candidates:
        # should not happen, but assign all zeros (invalid but safe)
        return [0] * n

    # Select candidate with fewest colors
    best = min(candidates, key=num_colors)
    best_k = num_colors(best)

    # Kempe chain color reduction
    def kempe_reduction(colors: list[int]) -> list[int]:
        nonlocal best_k
        changed = True
        while changed and best_k > 1:
            changed = False
            # identify color classes
            classes = [[] for _ in range(best_k)]
            for v in range(n):
                c = colors[v]
                if 0 <= c < best_k:
                    classes[c].append(v)
            # target the last color (best_k-1)
            target = best_k - 1
            if not classes[target]:
                # should not happen
                break
            # Try to recolor each vertex in target class
            for v in classes[target]:
                # Try direct reassignment to a lower color
                used = 0
                for u in adj_list[v]:
                    cu = colors[u]
                    if cu != -1:
                        used |= (1 << cu)
                for c in range(target):
                    if not (used & (1 << c)):
                        # move v to color c
                        colors[v] = c
                        changed = True
                        break
                if changed:
                    break
                # Try Kempe chains with each lower color
                for c in range(target):
                    # BFS to find the (v, c)-Kempe chain component containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in adj_list[x]:
                            if not visited[y]:
                                cy = colors[y]
                                if cy == c or cy == target:
                                    visited[y] = True
                                    queue.append(y)
                    # Check if any neighbor of v in the component has color c? Actually, we need to see if swapping frees color c for v.
                    # After swap, v would get color c if it is in the component (which it is) and we swap c<->target.
                    # But we must ensure that no neighbor of v ends up with color c after swap (which would cause conflict).
                    # Actually, after swap, neighbors of v that are in the component and had color c will become target, and those with target become c.
                    # So if v has a neighbor u with color c that is in the component, after swap u becomes target, so v can become c without conflict.
                    # However, if v has a neighbor u with color c that is NOT in the component, then after swap u remains c, so v cannot become c.
                    # Therefore, we can move v to color c if and only if there is NO neighbor of v with color c that is outside the component.
                    # Equivalent: all neighbors of v with color c are in the component.
                    has_external_c = False
                    for u in adj_list[v]:
                        if colors[u] == c and not visited[u]:
                            has_external_c = True
                            break
                    if not has_external_c:
                        # perform swap: c <-> target in the component
                        for x in component:
                            if colors[x] == c:
                                colors[x] = target
                            elif colors[x] == target:
                                colors[x] = c
                        changed = True
                        break
                if changed:
                    break
            if changed:
                # compact colors: reindex to 0..new_k-1
                # but we know we removed one color class? Not necessarily, we might have moved vertices but target class may still be non-empty.
                # Instead, we attempt to eliminate the target color class entirely by repeating until empty.
                # For simplicity, we just try to reduce the number of colors by one if possible.
                # Recompute classes and see if target class is empty
                classes = [[] for _ in range(best_k)]
                for v in range(n):
                    c = colors[v]
                    if 0 <= c < best_k:
                        classes[c].append(v)
                if not classes[target]:
                    # successful elimination: compact colors
                    mapping = {}
                    new_color = 0
                    for old in range(best_k):
                        if classes[old]:
                            mapping[old] = new_color
                            new_color += 1
                    for v in range(n):
                        if colors[v] in mapping:
                            colors[v] = mapping[colors[v]]
                    best_k = new_color
                else:
                    # cannot eliminate this round, break to avoid infinite loop
                    break
        return colors

    # Apply Kempe reduction
    improved = kempe_reduction(best[:])
    if is_valid_coloring(improved):
        final_k = num_colors(improved)
        if final_k < best_k:
            best = improved
            best_k = final_k
    # Ensure colors are contiguous 0..best_k-1
    # (Kempe reduction should maintain this, but re-map to be safe)
    used_colors = set(best)
    mapping = {}
    new_color = 0
    for old in sorted(used_colors):
        mapping[old] = new_color
        new_color += 1
    final = [mapping[c] for c in best]
    return final

