                        if u != w and (bit_adj[u] >> w) & 1:
                            degU += 1
                    if score > best_score or (score == best_score and degU < best_degU) or (score == best_score and degU == best_degU and random.random() < 0.5):
                        best_score = score
                        best_degU = degU
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u in U to W
                for w in list(U):
                    if (bit_adj[u] >> w) & 1:
                        U.remove(w)
                        W.add(w)
            # assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
        return compact_colors(color[:])

    # Smallest-Last ordering greedy
    def smallest_last():
        # compute degeneracy ordering
        # copy of degrees
        deg = [len(neighbors[u]) for u in range(n)]
        # buckets for degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        pos = [0] * n
        for v in range(n):
            d = deg[v]
            buckets[d].append(v)
            pos[v] = len(buckets[d]) - 1
        # current min degree
        min_deg = 0
        order = []
        # we will remove vertices
        removed = [False] * n
        for _ in range(n):
            # find first non-empty bucket from min_deg upwards
            while min_deg <= max_deg and not buckets[min_deg]:
                min_deg += 1
            if min_deg > max_deg:
                break  # should not happen
            v = buckets[min_deg].pop()
            pos[v] = -1  # mark removed
            removed[v] = True
            order.append(v)
            # update neighbors
            for u in neighbors[v]:
                if not removed[u]:
                    d = deg[u]
                    # remove u from bucket d
                    idx = pos[u]
                    last = buckets[d][-1]
                    buckets[d][idx] = last
                    pos[last] = idx
                    buckets[d].pop()
                    if not buckets[d]:
                        pass
                    deg[u] -= 1
                    d2 = deg[u]
                    buckets[d2].append(u)
                    pos[u] = len(buckets[d2]) - 1
                    if d2 < min_deg:
                        min_deg = d2
        # color in reverse order
        color = [-1] * n
        for v in reversed(order):
            used = set()
            for u in neighbors[v]:
                if color[u] != -1:
                    used.add(color[u])
            c = 0
            while c in used:
                c += 1
            color[v] = c
        return compact_colors(color[:])

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # make a copy we can modify
        color = coloring[:]
        # helper: get vertices of a color
        def color_class(c):
            return [v for v in range(n) if color[v] == c]
        # helper: check if moving v to color c is safe
        def can_move(v, c):
            for u in neighbors[v]:
                if color[u] == c:
                    return False
            return True
        # helper: Kempe chain (a,b) component containing v
        def kempe_component(v, a, b):
            if color[v] not in (a, b):
                return set()
            stack = [v]
            comp = set()
            while stack:
                u = stack.pop()
                if u in comp:
                    continue
                comp.add(u)
                for w in neighbors[u]:
                    if color[w] in (a, b) and w not in comp:
                        stack.append(w)
            return comp
        # main loop: try to eliminate color classes from highest down
        changed = True
        while changed:
            changed = False
            k = num_colors(color)
            # try to eliminate each color from k-1 down to 0
            for target in range(k-1, -1, -1):
                cls = color_class(target)
                if not cls:
                    continue
                # try to recolor each vertex in the class
                for v in cls:
                    # try direct move to a lower color
                    for c in range(target):
                        if can_move(v, c):
                            color[v] = c
                            changed = True
                            break
                    if color[v] != target:
                        # moved, break to restart scan
                        break
                    # try Kempe swaps
                    for c in range(target):
                        comp = kempe_component(v, target, c)
                        if not comp:
                            continue
                        # check if swapping frees color c for v
                        # after swap, v would get color c, so we need that no neighbor of v has color c after swap
                        # neighbors of v that are in comp will change from target to c or c to target
                        # we need that no neighbor of v has color c outside the comp (because inside comp they become target)
                        # Actually, we need that after swap, no neighbor of v has color c.
                        # For a neighbor u of v:
                        #   if u in comp: its color flips; if it was target -> becomes c, if it was c -> becomes target
                        #   if u not in comp: color unchanged
                        # So we need:
                        #   - no neighbor u of v with u not in comp and color[u] == c
                        #   - no neighbor u of v with u in comp and color[u] == target (because after swap becomes c)
                        conflict = False
                        for u in neighbors[v]:
                            if color[u] == c and u not in comp:
                                conflict = True
                                break
                            if color[u] == target and u in comp:
                                conflict = True
                                break
                        if not conflict:
                            # perform swap
                            for u in comp:
                                if color[u] == target:
                                    color[u] = c
                                else:
                                    color[u] = target
                            changed = True
                            break
                    if color[v] != target:
                        break
                if changed:
                    # after any change, break to restart from highest color
                    break
            # if we removed the highest color, compact
            if changed:
                # recompute k and compact if highest color class empty
                k = num_colors(color)
                if k > 0:
                    highest = k - 1
                    if not color_class(highest):
                        color = compact_colors(color)
        return color

    # Generate candidates
    candidates = []
    # DSATUR
    try:
        col_dsatur = dsatur()
        if is_valid(col_dsatur):
            candidates.append(col_dsatur)
    except Exception:
        pass
    # RLF
    try:
        col_rlf = rlf()
        if is_valid(col_rlf):
            candidates.append(col_rlf)
    except Exception:
        pass
    # Smallest-Last
    try:
        col_sl = smallest_last()
        if is_valid(col_sl):
            candidates.append(col_sl)
    except Exception:
        pass
    # If no candidate (should not happen), fallback to greedy
    if not candidates:
        color = [0] * n
        for u in range(n):
            used = set()
            for v in neighbors[u]:
                if color[v] != -1:
                    used.add(color[v])
            c = 0
            while c in used:
                c += 1
            color[u] = c
        candidates.append(compact_colors(color))
    # Apply Kempe reduction to each candidate and pick best
    best_coloring = None
    best_k = float('inf')
    for col in candidates:
        try:
            col_reduced = kempe_reduce(col[:])
            if is_valid(col_reduced):
                k = num_colors(col_reduced)
                if k < best_k:
                    best_k = k
                    best_coloring = col_reduced
        except Exception:
            continue
    if best_coloring is None:
        best_coloring = candidates[0]
    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j]:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if j < n:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: count bits in integer
    def bit_count(x):
        return x.bit_count()

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: compact colors to 0..k-1
    def compact_colors(coloring):
        if not coloring:
            return coloring
        # Map existing colors to 0..k-1
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    # DSATUR algorithm
    def dsatur():
        coloring = [-1] * n
        # saturation degree: number of distinct colors in neighbors
        sat = [0] * n
        # neighbor color sets as bit masks
        neighbor_colors = [0] * n

        # degrees for tie-breaking
        degrees = [len(adj_list[i]) for i in range(n)]

        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if coloring[u] == -1:
                    if sat[u] > max_sat or (sat[u] == max_sat and degrees[u] > max_deg) or \
                       (sat[u] == max_sat and degrees[u] == max_deg and random.random() < 0.5):
                        max_sat = sat[u]
                        max_deg = degrees[u]
                        v = u
            if v == -1:
                break  # should not happen

            # find smallest color not used by neighbors
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

            # update saturation and neighbor colors for neighbors
            for u in adj_list[v]:
                if coloring[u] == -1:
                    # add color c to neighbor's neighbor colors if not present
                    if not (neighbor_colors[u] & (1 << c)):
                        neighbor_colors[u] |= (1 << c)
                        sat[u] += 1

        return compact_colors(coloring)

    # RLF algorithm (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        color = 0
        # set of uncolored vertices
        uncolored = set(range(n))

        while uncolored:
            # build maximal independent set for this color
            # start with vertex of max degree in uncolored subgraph
            if not uncolored:
                break
            # compute degrees in uncolored subgraph
            deg_in_uncolored = {}
            for u in uncolored:
                cnt = 0
                for v in adj_list[u]:
                    if v in uncolored:
                        cnt += 1
                deg_in_uncolored[u] = cnt
            # pick vertex with max degree
            v = max(uncolored, key=lambda x: deg_in_uncolored[x])
            independent_set = {v}
            # partition remaining uncolored into U (not adj to S) and W (adj to S)
            U = uncolored - {v}
            W = set()
            for u in adj_list[v]:
                if u in U:
                    U.remove(u)
                    W.add(u)

            # while U not empty, add vertex with max neighbors in W
            while U:
                # select u in U with max |N(u) ∩ W|
                best_u = -1
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # count neighbors in W
                    w_neighbors = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_neighbors += 1
                    # tie-break by min degree in U
                    deg_in_U = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_in_U += 1
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and deg_in_U < min_deg_in_U) or \
                       (w_neighbors == max_w_neighbors and deg_in_U == min_deg_in_U and random.random() < 0.5):
                        max_w_neighbors = w_neighbors
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u == -1:
                    break
                # add best_u to independent set
                independent_set.add(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # assign color to all in independent set
            for u in independent_set:
                coloring[u] = color
            color += 1
            # next round: uncolored becomes W (vertices adjacent to current independent set)
            uncolored = W

        return compact_colors(coloring)

    # Smallest-Last (degeneracy ordering) greedy
    def smallest_last():
        # compute smallest-last ordering
        remaining = set(range(n))
        order = []
        degrees = [len(adj_list[i]) for i in range(n)]
        # we'll simulate peeling
        temp_deg = degrees[:]
        # maintain list of vertices by degree? Since n<=100, we can scan
        for _ in range(n):
            # find vertex with min temp_deg in remaining
            v = -1
            min_deg = float('inf')
            for u in remaining:
                if temp_deg[u] < min_deg:
                    min_deg = temp_deg[u]
                    v = u
            if v == -1:
                break
            order.append(v)
            remaining.remove(v)
            # decrease temp_deg of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    temp_deg[u] -= 1
        # color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        return compact_colors(coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # make a copy to work on
        current = coloring[:]
        changed = True
        while changed:
            changed = False
            k = num_colors(current)
            if k <= 1:
                break
            # target the last color (k-1)
            target_color = k - 1
            # vertices with target color
            target_vertices = [i for i in range(n) if current[i] == target_color]
            if not target_vertices:
                # should not happen if k is correct
                break
            # try to recolor each target vertex
            for v in target_vertices:
                # try direct reassignment to a lower color
                used_by_neighbors = 0
                for u in adj_list[v]:
                    if current[u] != -1:
                        used_by_neighbors |= (1 << current[u])
                # find smallest color not used by neighbors
                c = 0
                while c < target_color and (used_by_neighbors & (1 << c)):
                    c += 1
                if c < target_color:
                    # can recolor directly
                    current[v] = c
                    changed = True
                    break  # restart after change
                else:
                    # try Kempe chains with each lower color
                    for c in range(target_color):
                        # if neighbor already has color c, swapping won't help (would cause conflict)
                        has_c_neighbor = False
                        for u in adj_list[v]:
                            if current[u] == c:
                                has_c_neighbor = True
                                break
                        if has_c_neighbor:
                            continue
                        # build Kempe chain for colors (target_color, c) starting from v
                        # we want to see if we can swap in the component of v to free target_color
                        # Actually, we want to swap v's color (target_color) to c via Kempe chain
                        # Standard: consider subgraph induced by colors target_color and c
                        # Find connected component of v in that subgraph
                        stack = [v]
                        visited = set()
                        component = set()
                        while stack:
                            node = stack.pop()
                            if node in visited:
                                continue
                            visited.add(node)
                            if current[node] == target_color or current[node] == c:
                                component.add(node)
                                for nb in adj_list[node]:
                                    if nb not in visited and (current[nb] == target_color or current[nb] == c):
                                        stack.append(nb)
                        # Check if any neighbor of v in the component has color c? 
                        # Actually, if we swap colors in the component, v will become c.
                        # We need to ensure that no neighbor of v (outside the component) has color c,
                        # because after swap, v becomes c and would conflict.
                        # But note: neighbors of v that are in the component and have color c will become target_color, so no conflict.
                        # The only potential conflict is with neighbors of v that are not in the component but have color c.
                        safe = True
                        for u in adj_list[v]:
                            if u not in component and current[u] == c:
                                safe = False
                                break
                        if safe:
                            # perform swap: target_color <-> c in the component
                            for node in component:
                                if current[node] == target_color:
                                    current[node] = c
                                else:  # must be c
                                    current[node] = target_color
                            changed = True
                            break  # break from color loop
                    if changed:
                        break  # break from vertex loop
            # if we didn't change anything in this iteration, try to see if we can eliminate the color class entirely
            # by checking if all target vertices can be recolored (but we already tried one by one)
            # If no change, break
        # compact colors after reduction
        return compact_colors(current)

    # Run all heuristics
    best_coloring = None
    best_k = float('inf')

    # DSATUR
    c1 = dsatur()
    if is_valid_coloring(c1):
        k1 = num_colors(c1)
        if k1 < best_k:
            best_k = k1
            best_coloring = c1

    # RLF
    c2 = rlf()
    if is_valid_coloring(c2):
        k2 = num_colors(c2)
        if k2 < best_k:
            best_k = k2
            best_coloring = c2

    # Smallest-Last
    c3 = smallest_last()
    if is_valid_coloring(c3):
        k3 = num_colors(c3)
        if k3 < best_k:
            best_k = k3
            best_coloring = c3

    # Apply Kempe reduction to the best so far
    if best_coloring is not None:
        c4 = kempe_reduce(best_coloring[:])
        if is_valid_coloring(c4):
            k4 = num_colors(c4)
            if k4 < best_k:
                best_k = k4
                best_coloring = c4

    # Fallback: if somehow no coloring, use greedy by degree order
    if best_coloring is None:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        coloring = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        best_coloring = compact_colors(coloring)

    # Final validation and compact
    if not is_valid_coloring(best_coloring):
        # as a last resort, use trivial coloring (each vertex unique)
        best_coloring = list(range(n))
    best_coloring = compact_colors(best_coloring)

    return best_coloring

