    # Helper: compact colors to 0..k-1
    def compact_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]
    # DSATUR
    def dsatur():
        colors = [-1] * n
        colored_mask = 0
        sat = [0] * n
