            # select uncolored vertex with max saturation, tie-break by degree in uncolored, then index
            v = -1
            max_sat = -1
            max_deg = -1
            uncolored_mask = ((1 << n) - 1) & ~colored_mask
            for u in range(n):
                if colors[u] == -1:
                    sat_u = (bit_adj[u] & colored_mask).bit_count()
                    deg_u = degree_in_set(u, uncolored_mask)
                    if sat_u > max_sat or (sat_u == max_sat and (deg_u > max_deg or (deg_u == max_deg and u > v))):
                        max_sat = sat_u
