            # independent set for this color
            S_mask = 0
            # choose vertex with max degree in uncolored subgraph
            v = -1
            max_deg = -1
            temp = uncolored_mask
            while temp:
                u = (temp & -temp).bit_length() - 1
                deg_u = degree_in_set(u, uncolored_mask)
                if deg_u > max_deg or (deg_u == max_deg and u > v):
                    max_deg = deg_u
                    v = u
                temp &= temp - 1
            if v == -1:
