            while U_mask:
                # select u in U with max neighbors in W, tie-break by min degree in U, then index
                best_u = -1
                max_w_neighbors = -1
                min_deg_u = float('inf')
                temp = U_mask
                while temp:
                    u = (temp & -temp).bit_length() - 1
                    w_neighbors = degree_in_set(u, W_mask)
                    deg_u = degree_in_set(u, U_mask)
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and (deg_u < min_deg_u or (deg_u == min_deg_u and u > best_u))):
                        max_w_neighbors = w_neighbors
                        min_deg_u = deg_u
                        best_u = u
                    temp &= temp - 1
                if best_u == -1:
                    break
                S_mask |= 1 << best_u
                # move best_u from U to S, and its neighbors in U to W
                U_mask &= ~(1 << best_u)
                neighbors_in_U = bit_adj[best_u] & U_mask
                U_mask &= ~neighbors_in_U
                W_mask |= neighbors_in_U
            # assign color to all in S
            temp = S_mask
            while temp:
