                colors[u] = color
                temp &= temp - 1
            uncolored_mask &= ~S_mask
            color += 1
        return compact_colors(colors)
    # Smallest-Last ordering
    def smallest_last():
        if n == 0:
            return []
        # compute degeneracy ordering
        remaining = set(range(n))
        degree = [len(adj_list[u]) for u in range(n)]
        order = []
        # bucket sort by degree
        max_deg = max(degree) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[degree[u]].append(u)
        # pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            u = buckets[ptr].pop()
            order.append(u)
            remaining.remove(u)
            for v in adj_list[u]:
                if v in remaining:
                    d = degree[v]
                    if d > 0:
                        buckets[d].remove(v)
                        degree[v] -= 1
                        buckets[degree[v]].append(v)
                        if degree[v] < ptr:
                            ptr = degree[v]
        # color in reverse order
        colors = [-1] * n
        for u in reversed(order):
            neighbor_colors = 0
            for v in adj_list[u]:
                if colors[v] != -1:
                    neighbor_colors |= 1 << colors[v]
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[u] = c
        return compact_colors(colors)
    # Kempe chain swap for colors a and b, returns new coloring if swap performed, else None
    def kempe_swap(colors, a, b):
        n_local = len(colors)
        visited = [False] * n_local
        for start in range(n_local):
            if colors[start] == a or colors[start] == b:
                if not visited[start]:
                    # BFS to get component
                    stack = [start]
                    visited[start] = True
                    component = []
                    has_a = False
                    has_b = False
                    while stack:
                        u = stack.pop()
                        component.append(u)
                        if colors[u] == a:
                            has_a = True
                        elif colors[u] == b:
                            has_b = True
                        for v in adj_list[u]:
                            if not visited[v] and (colors[v] == a or colors[v] == b):
                                visited[v] = True
                                stack.append(v)
                    # if component does not contain both colors, swapping is safe
                    if not (has_a and has_b):
                        new_colors = colors[:]
                        for u in component:
                            if new_colors[u] == a:
                                new_colors[u] = b
                            elif new_colors[u] == b:
                                new_colors[u] = a
                        return new_colors
        return None
    # Try to eliminate a color using Kempe chains
    def reduce_colors_kempe(colors):
        k = num_colors_used(colors)
        if k <= 1:
            return colors
        # try to eliminate highest color
        target_color = k - 1
        # get vertices with target color
        target_vertices = [u for u in range(n) if colors[u] == target_color]
        # try to recolor each target vertex
        for v in target_vertices:
            # try direct reassignment to a lower color
            neighbor_colors = 0
            for u in adj_list[v]:
                if colors[u] != -1:
                    neighbor_colors |= 1 << colors[u]
            for c in range(target_color):
                if not (neighbor_colors & (1 << c)):
                    # can recolor directly
                    colors[v] = c
                    break
            else:
                # try Kempe chain swap with each lower color
                for c in range(target_color):
                    new_colors = kempe_swap(colors, target_color, c)
                    if new_colors is not None:
                        # check if the swap removed the target color from v
                        if new_colors[v] != target_color:
                            colors = new_colors
                            break
                else:
                    continue
                break
        # compact and check if we reduced
        colors = compact_colors(colors)
        new_k = num_colors_used(colors)
        if new_k < k:
            # recurse
            return reduce_colors_kempe(colors)
        return colors
    # Run all heuristics
    best_colors = None
    best_k = float('inf')
    for heuristic in [dsatur, rlf, smallest_last]:
        try:
            cols = heuristic()
            if is_valid_coloring(cols):
                k = num_colors_used(cols)
                if k < best_k:
                    best_k = k
                    best_colors = cols
        except Exception:
            continue
    # fallback: greedy by degree order
    if best_colors is None:
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        colors = [-1] * n
        for u in order:
            neighbor_colors = 0
            for v in adj_list[u]:
                if colors[v] != -1:
                    neighbor_colors |= 1 << colors[v]
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[u] = c
        best_colors = compact_colors(colors)
    # apply Kempe reduction
    best_colors = reduce_colors_kempe(best_colors)
    # final validation and compact
    if not is_valid_coloring(best_colors):
        # last resort: greedy
        order = list(range(n))
        colors = [-1] * n
        for u in order:
            neighbor_colors = 0
            for v in adj_list[u]:
                if colors[v] != -1:
                    neighbor_colors |= 1 << colors[v]
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[u] = c
        best_colors = compact_colors(colors)
    return best_colors

import math
