import time

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if input is adjacency matrix (square and binary)
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            for val in adj[i]:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: validate coloring
    def is_valid_coloring(colors):
        for u in range(n):
            cu = colors[u]
            for v in adj_list[u]:
                if cu == colors[v]:
                    return False
        return True

    # Helper: count distinct colors
    def count_colors(colors):
        return len(set(colors))

    # Helper: convert to consecutive 0..k-1
    def compact_colors(colors):
        mapping = {}
        next_color = 0
        for c in colors:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in colors]

    # DSATUR with degree tie-breaking
    def dsatur():
        colors = [-1] * n
        colored = [False] * n
        # Precompute neighbor bitsets for saturation
        # We'll compute saturation dynamically using bit_adj and a colored bitmask
        colored_mask = 0
        # Order by degree descending for tie-breaking in saturation
        degrees = [len(adj_list[i]) for i in range(n)]
        # We'll maintain a list of uncolored vertices
        uncolored = set(range(n))
        for _ in range(n):
            # Select vertex with max saturation, tie-break by degree (uncolored degree), then random
            best_v = -1
            best_sat = -1
            best_deg = -1
            for v in uncolored:
                # Compute saturation: number of distinct colors in neighbors
                neighbor_mask = bit_adj[v] & colored_mask
                sat = neighbor_mask.bit_count()
                # Current degree in uncolored subgraph: neighbors that are uncolored
                uncolored_neighbor_mask = bit_adj[v] & (~colored_mask) & ((1 << n) - 1)
                deg = uncolored_neighbor_mask.bit_count()
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and v > best_v):
                    best_sat = sat
                    best_deg = deg
                    best_v = v
            v = best_v
            # Find smallest color not used by neighbors
            neighbor_colors = 0
            nb_mask = bit_adj[v] & colored_mask
            while nb_mask:
                low = nb_mask & -nb_mask
                c = (low.bit_length() - 1)
                neighbor_colors |= (1 << c)
                nb_mask -= low
            # Find first zero bit in neighbor_colors
            c = 0
            while neighbor_colors & (1 << c):
                c += 1
            colors[v] = c
            colored[v] = True
            colored_mask |= (1 << v)
            uncolored.remove(v)
        return compact_colors(colors)

    # RLF (Recursive Largest First) independent set extraction
    def rlf():
        colors = [-1] * n
        uncolored_set = set(range(n))
        color = 0
        # Precompute degree in full graph for initial ordering
        full_deg = [len(adj_list[i]) for i in range(n)]
        while uncolored_set:
            # Build induced subgraph degrees for uncolored vertices
            deg_in_uncolored = {}
            for v in uncolored_set:
                # Count neighbors in uncolored_set
                cnt = 0
                for nb in adj_list[v]:
                    if nb in uncolored_set:
                        cnt += 1
                deg_in_uncolored[v] = cnt
            # Select vertex with max degree in G[R]
            v = max(uncolored_set, key=lambda x: (deg_in_uncolored[x], full_deg[x], x))
            # Independent set for this color
            S = {v}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set()
            W = set()
            for u in uncolored_set:
                if u == v:
                    continue
                adjacent_to_S = False
                for s in S:
                    if u in adj_list[s]:
                        adjacent_to_S = True
                        break
                if adjacent_to_S:
                    W.add(u)
                else:
                    U.add(u)
            # While U not empty, add vertices to S
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_U = -1
                for u in U:
                    # Score: number of neighbors in W
                    score = 0
                    for nb in adj_list[u]:
                        if nb in W:
                            score += 1
                    # Tie-break: min degree in G[U]
                    deg_U = 0
                    for nb in adj_list[u]:
                        if nb in U:
                            deg_U += 1
                    if score > best_score or (score == best_score and deg_U < best_deg_U) or (score == best_score and deg_U == best_deg_U and u > best_u):
                        best_score = score
                        best_deg_U = deg_U
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for nb in adj_list[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to all in S
            for vertex in S:
                colors[vertex] = color
                uncolored_set.remove(vertex)
            color += 1
        return compact_colors(colors)

    # Smallest-Last (Matula & Beck) ordering greedy
    def smallest_last():
        # Build core ordering: repeatedly remove min degree vertex
        deg = [len(adj_list[i]) for i in range(n)]
        removed = [False] * n
        order = []  # will hold vertices in removal order
        # We'll use buckets for efficiency, but n<=100 so simple scan is fine
        for _ in range(n):
            # Find vertex with minimum degree among non-removed
            min_deg = float('inf')
            v = -1
            for i in range(n):
                if not removed[i] and deg[i] < min_deg:
                    min_deg = deg[i]
                    v = i
            if v == -1:
                break  # should not happen
            removed[v] = True
            order.append(v)
            # Decrease degree of neighbors
            for nb in adj_list[v]:
                if not removed[nb]:
                    deg[nb] -= 1
        # Color in reverse order
        colors = [-1] * n
        for v in reversed(order):
            # Find smallest color not used by neighbors
            used = [False] * (n + 1)  # safe upper bound
            for nb in adj_list[v]:
                c = colors[nb]
                if c != -1:
                    used[c] = True
            c = 0
            while used[c]:
                c += 1
            colors[v] = c
        return compact_colors(colors)

    # Kempe chain color reduction
    def kempe_reduce(colors):
        # Make a copy we can modify
        col = colors[:]
        k = count_colors(col)
        # Try to reduce from k down to 1
        improved = True
        while improved and k > 1:
            improved = False
            # Target the largest color index (k-1) for elimination
            target_color = k - 1
            # Get vertices with target_color
            target_vertices = [v for v in range(n) if col[v] == target_color]
            if not target_vertices:
                # Already compacted?
                col = compact_colors(col)
                k = count_colors(col)
                continue
            # Try to recolor each target vertex
            for v in target_vertices:
                # Try direct reassignment to a lower color
                neighbor_colors = set()
                for nb in adj_list[v]:
                    cnb = col[nb]
                    if cnb != -1:
                        neighbor_colors.add(cnb)
                for c in range(target_color):  # try colors 0..target_color-1
                    if c not in neighbor_colors:
                        col[v] = c
                        improved = True
                        break
                if improved:
                    # After moving v, check if target_color class is empty
                    if target_color not in col:
                        col = compact_colors(col)
                        k = count_colors(col)
                        break
                    else:
                        # Revert and try Kempe chains
                        col[v] = target_color
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Check if v can be swapped via (c, target_color) Kempe chain
                    # We'll build the component containing v in the subgraph of colors c and target_color
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for nb in adj_list[x]:
                            if not visited[nb] and (col[nb] == c or col[nb] == target_color):
                                visited[nb] = True
                                queue.append(nb)
                    # In this component, check if there is any neighbor of v (in original graph) with color c
                    # that is NOT in the component? Actually, we need to see if swapping would cause conflict.
                    # After swap, v would get color c. We need to ensure no neighbor of v has color c after swap.
                    # Neighbors of v that are in the component: if they have color c, they become target_color -> ok.
                    # Neighbors of v that are not in the component: if they have color c, they remain c -> conflict.
                    conflict = False
                    for nb in adj_list[v]:
                        if col[nb] == c and not visited[nb]:
                            conflict = True
                            break
                    if not conflict:
                        # Perform swap: c <-> target_color in component
                        for x in component:
                            if col[x] == c:
                                col[x] = target_color
                            elif col[x] == target_color:
                                col[x] = c
                        improved = True
                        # Check if target_color class is now empty
                        if target_color not in col:
                            col = compact_colors(col)
                            k = count_colors(col)
                            break
                if improved and (target_color not in col):
                    break
            # If we couldn't eliminate target_color, break
            if not improved:
                break
        return col

    # Generate candidate colorings
    start_time = time.time()
    candidates = []

    # Run DSATUR
    t0 = time.time()
    c1 = dsatur()
    t1 = time.time()
    if is_valid_coloring(c1):
        candidates.append(c1)

    # Run RLF
    c2 = rlf()
    t2 = time.time()
    if is_valid_coloring(c2):
        candidates.append(c2)

    # Run Smallest-Last
    c3 = smallest_last()
    t3 = time.time()
    if is_valid_coloring(c3):
        candidates.append(c3)

    # If no candidate (shouldn't happen), fallback to greedy
    if not candidates:
        # Simple greedy in vertex order
        colors = [-1] * n
        for i in range(n):
            used = [False] * (n + 1)
            for nb in adj_list[i]:
                cnb = colors[nb]
                if cnb != -1:
                    used[cnb] = True
            c = 0
            while used[c]:
                c += 1
            colors[i] = c
        candidates.append(compact_colors(colors))

    # Select best candidate (fewest colors)
    best = min(candidates, key=lambda x: (count_colors(x), x))
    best = kempe_reduce(best)
    # Final validation and compaction
    if not is_valid_coloring(best):
        # Should not happen, but fallback to DSATUR
        best = dsatur()
    best = compact_colors(best)
    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if entries are binary (0 or 1)
        all_binary = True
        for row in adj:
            for val in row:
                if val not in (0, 1):
                    all_binary = False
                    break
            if not all_binary:
                break
        if all_binary:
            is_matrix = True

    # Convert to internal adjacency list and bitmask
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        bit_adj = [0] * n
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        adj_list = adj
        bit_adj = [0] * n
        for u in range(n):
            for v in adj_list[u]:
                bit_adj[u] |= (1 << v)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            # Find smallest color not used
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count unique colors
    def count_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    best_coloring = None
    best_k = float('inf')

    # 1. DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        saturation = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(adj_list[i]) for i in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # Select vertex with max saturation, tie-break by max degree in uncolored, then random
            max_sat = -1
            candidates = []
            for v in uncolored:
                sat = saturation[v].bit_count()
                if sat > max_sat:
                    max_sat = sat
                    candidates = [v]
                elif sat == max_sat:
                    candidates.append(v)

            if len(candidates) > 1:
                # Tie-break by degree in uncolored subgraph
                max_deg = -1
                deg_candidates = []
                for v in candidates:
                    deg = uncolored_deg[v]
                    if deg > max_deg:
                        max_deg = deg
                        deg_candidates = [v]
                    elif deg == max_deg:
                        deg_candidates.append(v)
                if len(deg_candidates) > 1:
                    v = random.choice(deg_candidates)
                else:
                    v = deg_candidates[0]
            else:
                v = candidates[0]

            # Assign smallest available color
            used = 0
            for u in adj_list[v]:
                c = color[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c

            # Update uncolored set and degrees
            uncolored.remove(v)
            for u in adj_list[v]:
                if u in uncolored:
                    uncolored_deg[u] -= 1
                    # Update saturation: add color c to u's saturation
                    saturation[u] |= (1 << c)
        return color

    # 2. RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        current_color = 0

        while uncolored:
            # Build independent set for current_color
            # Step 1: pick vertex with max degree in G[uncolored]
            max_deg = -1
            v1 = None
            for v in uncolored:
                deg = 0
                for u in adj_list[v]:
                    if u in uncolored:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v1 = v
            if v1 is None:
                break  # should not happen

            S = {v1}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set()
            W = set()
            for v in uncolored:
                if v == v1:
                    continue
                adjacent = False
                for u in S:
                    if v in adj_list[u]:
                        adjacent = True
                        break
                if adjacent:
                    W.add(v)
                else:
                    U.add(v)

            # While U not empty, add vertex with max neighbors in W
            while U:
                best_u = None
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # Count neighbors in W
                    w_count = 0
                    for w in adj_list[u]:
                        if w in W:
                            w_count += 1
                    # Tie-break: min degree in G[U]
                    deg_in_U = 0
                    for w in adj_list[u]:
                        if w in U:
                            deg_in_U += 1
                    if w_count > max_w_neighbors or (w_count == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_count
                        min_deg_in_U = deg_in_U
                        best_u = u
                if best_u is None:
                    break  # should not happen
                S.add(best_u)
                U.remove(best_u)
                # Move neighbors of best_u from U to W
                for w in adj_list[best_u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color to all in S
            for v in S:
                color[v] = current_color
            uncolored -= S
            current_color += 1
        return color

    # 3. Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering by repeatedly removing min degree vertex
        degree = [len(adj_list[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # We'll use buckets for efficiency, but n <= 100 so simple scan is fine
        for _ in range(n):
            min_deg = float('inf')
            v = -1
            for i in range(n):
                if not removed[i] and degree[i] < min_deg:
                    min_deg = degree[i]
                    v = i
            if v == -1:
                break
            removed[v] = True
            order.append(v)
            for u in adj_list[v]:
                if not removed[u]:
                    degree[u] -= 1
        # Color in reverse order
        return greedy_color(order[::-1])

    # 4. Welsh-Powell (sort by degree descending)
    def welsh_powell():
        order = sorted(range(n), key=lambda x: len(adj_list[x]), reverse=True)
        return greedy_color(order)

    # Generate candidate colorings
    candidates = []
    for func in [dsatur, rlf, smallest_last, welsh_powell]:
        try:
            coloring = func()
            k = count_colors(coloring)
            if k < best_k:
                best_k = k
                best_coloring = coloring[:]
        except Exception:
            continue

    # If no candidate succeeded, fall back to simple greedy
    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_k = count_colors(best_coloring)

    # Kempe chain color reduction
    def kempe_reduce(coloring):
        # Make a copy to work on
        color = coloring[:]
        changed = True
        while changed:
            changed = False
            # Find smallest color class (largest color index that is used)
            # We'll try to eliminate the highest color index first
            max_color = max(color) if color else -1
            for target_color in range(max_color, -1, -1):
                # Collect vertices with this color
                verts = [v for v in range(n) if color[v] == target_color]
                if not verts:
                    continue
                # Try to recolor each vertex in this class
                for v in verts:
                    # Try direct reassignment to a lower color
                    used_by_neighbors = 0
                    for u in adj_list[v]:
                        c = color[u]
                        if c != -1:
                            used_by_neighbors |= (1 << c)
                    # Find smallest available color < target_color
                    for c in range(target_color):
                        if not (used_by_neighbors & (1 << c)):
                            # Recolor v to c
                            color[v] = c
                            changed = True
                            break
                    if changed:
                        break
                    # If direct reassignment not possible, try Kempe chains
                    for c in range(target_color):
                        # Check if v can be swapped via Kempe chain (target_color, c)
                        # We need to see if v is in a component that doesn't contain any vertex of color c
                        # that is adjacent to v? Actually, standard: if the Kempe chain of v in colors {target_color, c}
                        # does not contain any neighbor of v colored c, then we can swap.
                        # But simpler: if there is no path from v to any vertex of color c using only colors target_color and c,
                        # then we can swap the component containing v.
                        # We'll do BFS/DFS on the subgraph induced by colors target_color and c.
                        from collections import deque
                        visited = [False] * n
                        queue = deque([v])
                        visited[v] = True
                        component = set([v])
                        has_c_neighbor = False  # whether component has a vertex adjacent to a c-colored vertex outside?
                        # Actually, we need to check if swapping would cause conflict: after swap, v becomes c.
                        # It will conflict if any neighbor of v is c (and not swapped).
                        # So we need that in the component, there is no vertex that is adjacent to a c-colored vertex
                        # that is not in the component (because that neighbor would remain c and cause conflict).
                        # Standard condition: the component should not contain any vertex that is adjacent to a vertex of color c
                        # that is not in the component.
                        # We'll compute: for each vertex in component, check its neighbors that are color c and not in component.
                        # If any such neighbor exists, swapping would cause conflict.
                        while queue:
                            x = queue.popleft()
                            for u in adj_list[x]:
                                if color[u] == target_color or color[u] == c:
                                    if not visited[u]:
                                        visited[u] = True
                                        queue.append(u)
                                        component.add(u)
                                # If u is colored c and not in component, then x is adjacent to a c-colored vertex outside
                                if color[u] == c and u not in component:
                                    has_c_neighbor = True
                        # If no such external c-colored neighbor, we can swap
                        if not has_c_neighbor:
                            # Swap colors target_color and c in the component
                            for x in component:
                                if color[x] == target_color:
                                    color[x] = c
                                elif color[x] == c:
                                    color[x] = target_color
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    break
            # If we made a change, break and restart from highest color
            if changed:
                break
        # Compact colors: remap to 0..k-1
        # Get unique colors used
        unique_colors = sorted(set(color))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        for i in range(n):
            color[i] = mapping[color[i]]
        return color

    # Apply Kempe reduction
    try:
        best_coloring = kempe_reduce(best_coloring)
    except Exception:
        pass  # If kempe fails, keep the coloring we have

    # Final validation and compacting (ensure 0..k-1)
    # Compact colors
    unique_colors = sorted(set(best_coloring))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    for i in range(n):
        best_coloring[i] = mapping[best_coloring[i]]

    # Validate (optional, but good for debugging)
    # for u in range(n):
    #     for v in adj_list[u]:
    #         if best_coloring[u] == best_coloring[v]:
    #             # Invalid coloring, but we hope it doesn't happen
    #             pass

    return best_coloring

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    # Determine if input is adjacency matrix
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        for row in adj:
            if len(row) != n:
                is_matrix = False
                break
            for val in row:
                if val not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break
    # Build adjacency list and bitmask representation
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for v in adj[i]:
                neighbors[i].append(v)
                bit_adj[i] |= (1 << v)
    # Helper to get degree in a subgraph defined by a mask
    def degree_in_mask(v, mask):
        return (bit_adj[v] & mask).bit_count()
    # Helper to get saturation degree (distinct colors in neighbors)
    def saturation_degree(v, colors):
        mask = 0
        for u in neighbors[v]:
            c = colors[u]
            if c != -1:
                mask |= (1 << c)
        return mask.bit_count()
    # DSATUR
    def dsatur():
        colors = [-1] * n
        # Order by degree descending for tie-breaking in saturation
        degree = [len(neighbors[i]) for i in range(n)]
        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for i in range(n):
                if colors[i] == -1:
                    sat = saturation_degree(i, colors)
                    if sat > max_sat or (sat == max_sat and degree[i] > max_deg) or \
                       (sat == max_sat and degree[i] == max_deg and random.random() < 0.5):
                        max_sat = sat
                        max_deg = degree[i]
                        v = i
            # Assign smallest available color
            used = 0
            for u in neighbors[v]:
                c = colors[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors
    # RLF (Recursive Largest First)
    def rlf():
        colors = [-1] * n
        color = 0
        uncolored_mask = (1 << n) - 1
        while uncolored_mask:
            # Build independent set for this color
            S_mask = 0
            # Choose vertex with max degree in uncolored subgraph
            v = -1
            max_deg = -1
            temp = uncolored_mask
            while temp:
                lsb = temp & -temp
                i = (lsb.bit_length() - 1)
                deg = degree_in_mask(i, uncolored_mask)
                if deg > max_deg:
                    max_deg = deg
                    v = i
                temp -= lsb
            S_mask |= (1 << v)
            # U: vertices not adjacent to S (eligible)
            # W: vertices adjacent to S (ineligible)
            neighbor_S_mask = 0
            temp = S_mask
            while temp:
                lsb = temp & -temp
                i = (lsb.bit_length() - 1)
                neighbor_S_mask |= bit_adj[i]
                temp -= lsb
            U_mask = uncolored_mask & ~neighbor_S_mask
            W_mask = uncolored_mask & neighbor_S_mask
            # Grow independent set
            while U_mask:
                # Select u in U with max |N(u) ∩ W|
                u = -1
                max_w_neighbors = -1
                min_deg_U = float('inf')
                temp = U_mask
                while temp:
                    lsb = temp & -temp
                    i = (lsb.bit_length() - 1)
                    w_neighbors = degree_in_mask(i, W_mask)
                    deg_U = degree_in_mask(i, U_mask)
                    if w_neighbors > max_w_neighbors or \
                       (w_neighbors == max_w_neighbors and deg_U < min_deg_U) or \
                       (w_neighbors == max_w_neighbors and deg_U == min_deg_U and random.random() < 0.5):
                        max_w_neighbors = w_neighbors
                        min_deg_U = deg_U
                        u = i
                    temp -= lsb
                # Add u to S
                S_mask |= (1 << u)
                # Update U and W: remove u from U, add its neighbors in U to W
                U_mask &= ~(1 << u)
                nbrs_u = bit_adj[u] & U_mask
                W_mask |= nbrs_u
                U_mask &= ~nbrs_u
            # Assign color to all in S
            temp = S_mask
            while temp:
                lsb = temp & -temp
                i = (lsb.bit_length() - 1)
                colors[i] = color
                temp -= lsb
            color += 1
            uncolored_mask = W_mask
        return colors
    # Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        colors = [-1] * n
        # Compute removal order (smallest last)
        degree = [len(neighbors[i]) for i in range(n)]
        removed = [False] * n
        order = []
        # Use buckets for efficiency (max degree <= n-1)
        max_deg = n - 1
        buckets = [[] for _ in range(max_deg + 1)]
        for i in range(n):
            d = degree[i]
            buckets[d].append(i)
        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            removed[v] = True
            order.append(v)
            # Update neighbors
            for u in neighbors[v]:
                if not removed[u]:
                    d = degree[u]
                    # Remove u from bucket d
                    if u in buckets[d]:
                        buckets[d].remove(u)
                    degree[u] -= 1
                    d_new = degree[u]
                    buckets[d_new].append(u)
                    if d_new < ptr:
                        ptr = d_new
        # Color in reverse order
        for v in reversed(order):
            used = 0
            for u in neighbors[v]:
                c = colors[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        return colors
    # Kempe chain color reduction
    def kempe_reduce(colors):
        # Helper to get Kempe chain component for colors a,b starting from v
        def kempe_component(v, a, b, colors):
            if colors[v] not in (a, b):
                return 0
            stack = [v]
            comp = 0
            seen = 0
            seen |= (1 << v)
            while stack:
                node = stack.pop()
                comp |= (1 << node)
                for nb in neighbors[node]:
                    if colors[nb] in (a, b) and not (seen & (1 << nb)):
                        seen |= (1 << nb)
                        stack.append(nb)
            return comp
        # Try to eliminate color classes from highest downward
        changed = True
        while changed:
            changed = False
            max_color = max(colors) if colors else -1
            for target_color in range(max_color, 0, -1):
                # Collect vertices with target_color
                targets = [i for i in range(n) if colors[i] == target_color]
                if not targets:
                    continue
                # Try to recolor each target vertex
                for v in targets:
                    # Try direct reassignment to a lower color
                    used = 0
                    for u in neighbors[v]:
                        c = colors[u]
                        if c != -1:
                            used |= (1 << c)
                    for c in range(target_color):
                        if not (used & (1 << c)):
                            colors[v] = c
                            changed = True
                            break
                    if changed:
                        break
                    # Try Kempe chain swap with each lower color
                    for c in range(target_color):
                        # Check if v can be moved to color c via Kempe chain
                        comp = kempe_component(v, target_color, c, colors)
                        if comp == 0:
                            continue  # should not happen
                        # Determine if swapping comp frees color c for v
                        # After swap, v would have color c; check if any neighbor of v has color c (outside comp)
                        conflict = False
                        for u in neighbors[v]:
                            if colors[u] == c and not (comp & (1 << u)):
                                conflict = True
                                break
                        if not conflict:
                            # Perform swap: flip colors in comp
                            for i in range(n):
                                if comp & (1 << i):
                                    if colors[i] == target_color:
                                        colors[i] = c
                                    else:
                                        colors[i] = target_color
                            changed = True
                            break
                    if changed:
                        break
                if changed:
                    # Compact colors: reindex to 0..k-1
                    # Build mapping from old colors to new consecutive colors
                    unique_colors = {}
                    next_color = 0
                    for i in range(n):
                        c = colors[i]
                        if c not in unique_colors:
                            unique_colors[c] = next_color
                            next_color += 1
                    for i in range(n):
                        colors[i] = unique_colors[colors[i]]
                    break  # restart while changed loop
        return colors
    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        # Validate
        ok = True
        for i in range(n):
            for j in neighbors[i]:
                if i < j and c1[i] == c1[j]:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            candidates.append(c1)
    except Exception:
        pass
    # RLF
    try:
        c2 = rlf()
        ok = True
        for i in range(n):
            for j in neighbors[i]:
                if i < j and c2[i] == c2[j]:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            candidates.append(c2)
    except Exception:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        ok = True
        for i in range(n):
            for j in neighbors[i]:
                if i < j and c3[i] == c3[j]:
                    ok = False
                    break
            if not ok:
                break
        if ok:
            candidates.append(c3)
    except Exception:
        pass
    # If no candidate (should not happen), fall back to greedy
    if not candidates:
        colors = [-1] * n
        order = list(range(n))
        order.sort(key=lambda x: len(neighbors[x]), reverse=True)
        for v in order:
            used = 0
            for u in neighbors[v]:
                c = colors[u]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            colors[v] = c
        candidates.append(colors)
    # Apply Kempe reduction to each candidate and pick best
    best_colors = None
    best_k = float('inf')
    for col in candidates:
        try:
            col_reduced = kempe_reduce(col[:])  # work on a copy
            k = len(set(col_reduced))
            if k < best_k:
                best_k = k
                best_colors = col_reduced
        except Exception:
            k = len(set(col))
            if k < best_k:
                best_k = k
                best_colors = col
    # Final validation and compacting (ensure 0..k-1)
    if best_colors is None:
        best_colors = candidates[0]
    # Compact colors
    mapping = {}
    next_c = 0
    for i in range(n):
        c = best_colors[i]
        if c not in mapping:
            mapping[c] = next_c
            next_c += 1
        best_colors[i] = mapping[best_colors[i]]
    return best_colors

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    """
    Colors a graph using a hybrid heuristic approach combining DSATUR, RLF, 
    and smallest-last ordering, followed by Kempe chain-based color reduction.
    Designed to run within 50ms for N <= 100.
    """
    start_time = time.time()

    # Helper to check time budget
    def time_up():
        return time.time() - start_time > 0.045  # Leave buffer for overhead

    # Handle trivial cases
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect input format and convert to adjacency list
    if len(adj) > 0 and len(adj[0]) == n and all(
        isinstance(x, int) and x in (0, 1) for row in adj for x in row
    ):
        # Adjacency matrix
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        # Adjacency list
        adj_list = adj
        # Ensure symmetry (undirected graph)
        for u in range(n):
            for v in adj_list[u]:
                if u not in adj_list[v]:
                    adj_list[v].append(u)

    # Convert to bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            bit_adj[u] |= (1 << v)

    # Helper: check if coloring is valid
    def is_valid_coloring(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: get number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: normalize colors to 0..k-1
    def normalize_colors(coloring):
        if not coloring:
            return coloring
        # Map used colors to 0..k-1
        unique_colors = sorted(set(coloring))
        mapping = {old: new for new, old in enumerate(unique_colors)}
        return [mapping[c] for c in coloring]

    # Strategy 1: DSATUR with degree tie-breaking
    def dsatur():
        if time_up():
            return None
        coloring = [-1] * n
        # saturation[v] = number of distinct colors in neighbors
        saturation = [0] * n
        # neighbor_colors[v] = bitmask of colors used by neighbors
        neighbor_colors = [0] * n

        # Degree for tie-breaking
        degrees = [len(adj_list[u]) for u in range(n)]

        # Select first vertex: max degree
        v = max(range(n), key=lambda u: degrees[u])
        coloring[v] = 0
        # Update neighbors
        for u in adj_list[v]:
            neighbor_colors[u] |= (1 << 0)
            saturation[u] = neighbor_colors[u].bit_count()

        colored_count = 1
        while colored_count < n:
            if time_up():
                return None
            # Find uncolored vertex with max saturation
            candidates = []
            max_sat = -1
            for u in range(n):
                if coloring[u] == -1:
                    sat = saturation[u]
                    if sat > max_sat:
                        max_sat = sat
                        candidates = [u]
                    elif sat == max_sat:
                        candidates.append(u)

            if not candidates:
                break  # Should not happen

            # Tie-break: max degree in uncolored subgraph
            def uncolored_degree(u):
                return sum(1 for v in adj_list[u] if coloring[v] == -1)

            v = max(candidates, key=lambda u: (uncolored_degree(u), degrees[u], -u))

            # Find smallest available color
            used = neighbor_colors[v]
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

            # Update neighbors
            for u in adj_list[v]:
                if not (neighbor_colors[u] & (1 << c)):
                    neighbor_colors[u] |= (1 << c)
                    saturation[u] = neighbor_colors[u].bit_count()

            colored_count += 1

        return normalize_colors(coloring)

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        if time_up():
            return None
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0

        while uncolored:
            if time_up():
                return None
            # Build independent set for this color
            S = []
            # Step 1: pick vertex with max degree in G[uncolored]
            def deg_in_uncolored(u):
                return sum(1 for v in adj_list[u] if v in uncolored)

            v = max(uncolored, key=deg_in_uncolored)
            S.append(v)
            uncolored.remove(v)

            # Partition: U = not adjacent to S, W = adjacent to S
            U = {u for u in uncolored if all((u not in adj_list[s]) for s in S)}
            W = uncolored - U

            while U:
                if time_up():
                    return None
                # Select u in U with max |N(u) ∩ W|
                def weight(u):
                    return sum(1 for v in adj_list[u] if v in W)

                # Tie-break: min degree in G[U]
                def deg_in_U(u):
                    return sum(1 for v in adj_list[u] if v in U)

                u = max(U, key=lambda x: (weight(x), -deg_in_U(x), -x))
                S.append(u)
                U.remove(u)
                # Move neighbors of u from U to W
                nbrs_in_U = {v for v in adj_list[u] if v in U}
                U -= nbrs_in_U
                W |= nbrs_in_U

            # Assign color to all in S
            for v in S:
                coloring[v] = color
            color += 1

        return normalize_colors(coloring)

    # Strategy 3: Smallest-Last (Matula-Beck) ordering
    def smallest_last():
        if time_up():
            return None
        # Peeling order: remove min degree vertex repeatedly
        remaining = set(range(n))
        degree = [len(adj_list[u]) for u in range(n)]
        order = []  # will be peeled order (min degree first)

        # Current degrees in remaining graph
        curr_degree = degree[:]
        # For efficiency, we'll recompute when needed (n <= 100)

        while remaining:
            if time_up():
                return None
            # Find vertex with minimum current degree
            v = min(remaining, key=lambda u: (curr_degree[u], u))
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for u in adj_list[v]:
                if u in remaining:
                    curr_degree[u] -= 1

        # Color in reverse order (last peeled first)
        coloring = [-1] * n
        for v in reversed(order):
            # Find smallest color not used by colored neighbors
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c

        return normalize_colors(coloring)

    # Run all strategies and pick best
    strategies = [
        ("DSATUR", dsatur),
        ("RLF", rlf),
        ("Smallest-Last", smallest_last)
    ]

    best_coloring = None
    best_k = float('inf')

    for name, strategy in strategies:
        if time_up():
            break
        coloring = strategy()
        if coloring is None:
            continue
        if not is_valid_coloring(coloring):
            continue
        k = num_colors(coloring)
        if k < best_k:
            best_k = k
            best_coloring = coloring

    # Fallback: greedy by degree if all failed
    if best_coloring is None:
        # Simple greedy: order by degree descending
        order = sorted(range(n), key=lambda u: len(adj_list[u]), reverse=True)
        coloring = [-1] * n
        for v in order:
            used = 0
            for u in adj_list[v]:
                if coloring[u] != -1:
                    used |= (1 << coloring[u])
            c = 0
            while used & (1 << c):
                c += 1
            coloring[v] = c
        best_coloring = normalize_colors(coloring)
        if not is_valid_coloring(best_coloring):
            # Last resort: assign each vertex unique color
            best_coloring = list(range(n))

    # Kempe chain-based color reduction
    def kempe_reduce(coloring):
        if time_up():
            return coloring
        # Make a copy to work on
        current = coloring[:]
        k = num_colors(current)

        # Try to eliminate color classes from highest downward
        for target_color in range(k-1, 0, -1):
            if time_up():
                break
            # Get vertices with target_color
            verts = [v for v in range(n) if current[v] == target_color]
            if not verts:
                continue  # already eliminated

            eliminated = True
            new_coloring = current[:]  # work on copy

            for v in verts:
                if time_up():
                    break
                # Try to recolor v to a lower color
                # First, try direct reassignment
                neighbor_colors = 0
                for u in adj_list[v]:
                    if new_coloring[u] != -1:
                        neighbor_colors |= (1 << new_coloring[u])

                found = False
                for c in range(target_color):  # only try colors < target_color
                    if not (neighbor_colors & (1 << c)):
                        new_coloring[v] = c
                        found = True
                        break

                if found:
                    continue

                # Try Kempe chains with each lower color
                kempe_found = False
                for c in range(target_color):
                    if time_up():
                        break
                    # Skip if v already has color c (shouldn't happen)
                    if new_coloring[v] == c:
                        continue

                    # Find the Kempe chain component containing v for colors (target_color, c)
                    # We'll do BFS/DFS on the subgraph induced by vertices with color target_color or c
                    from collections import deque
                    visited = [False] * n
                    component = []
                    queue = deque([v])
                    visited[v] = True

                    while queue:
                        node = queue.popleft()
                        component.append(node)
                        for nb in adj_list[node]:
                            if not visited[nb] and new_coloring[nb] in (target_color, c):
                                visited[nb] = True
                                queue.append(nb)

                    # Check if swapping this component is safe:
                    # After swap, no neighbor of any node in component should have the new color
                    # For nodes currently target_color -> become c: check no neighbor has c
                    # For nodes currently c -> become target_color: check no neighbor has target_color
                    safe = True
                    for node in component:
                        col = new_coloring[node]
                        new_col = target_color if col == c else c
                        for nb in adj_list[node]:
                            nb_col = new_coloring[nb]
                            if nb_col == new_col:
                                safe = False
                                break
                        if not safe:
                            break

                    if safe:
                        # Perform the swap
                        for node in component:
                            if new_coloring[node] == target_color:
                                new_coloring[node] = c
                            else:
                                new_coloring[node] = target_color
                        kempe_found = True
                        break  # break from color loop

                if not kempe_found:
