            v = max(uncolored, key=lambda u: (deg[u], random.random()))
            # independent set S
            S = {v}
            # U: vertices not adjacent to S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = uncolored - {v} - set(graph[v])
            W = set(graph[v]) & uncolored
            while U:
                # select u in U with max neighbors in W, tie-break by min degree in U
                best_u = -1
                max_w_neighbors = -1
                min_deg_u = float('inf')
                for u in U:
                    w_neighbors = sum(1 for nb in graph[u] if nb in W)
                    deg_u = sum(1 for nb in graph[u] if nb in U)
                    if w_neighbors > max_w_neighbors or (w_neighbors == max_w_neighbors and deg_u < min_deg_u):
                        max_w_neighbors = w_neighbors
                        min_deg_u = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # move neighbors of u from U to W
                for nb in graph[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # assign color to all in S
            for u in S:
                coloring[u] = color
            uncolored -= S
            color += 1
        return coloring

    # Strategy 3: Smallest-Last (Matula & Beck) ordering
    def smallest_last():
        # compute degeneracy ordering
        order = []
        degrees = [len(graph[u]) for u in range(n)]
        # buckets for degree
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[degrees[u]].append(u)
        # pointer to current non-empty bucket
        ptr = 0
        # copy of degrees
        deg = degrees[:]
        # removed flag
        removed = [False] * n
        for _ in range(n):
            # find next non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            # remove vertex from bucket
            u = buckets[ptr].pop()
            while removed[u]:
                if not buckets[ptr]:
                    break
                u = buckets[ptr].pop()
            if removed[u]:
                continue
            removed[u] = True
            order.append(u)
            # update neighbors
            for v in graph[u]:
                if not removed[v]:
                    d = deg[v]
                    if d > 0:
                        deg[v] -= 1
                        buckets[d].remove(v)
                        buckets[d-1].append(v)
        # color in reverse order
        coloring = [-1] * n
        for u in reversed(order):
            # neighbor colors
            mask = 0
            for v in graph[u]:
                if coloring[v] != -1:
                    mask |= 1 << coloring[v]
            coloring[u] = first_fit(mask)
        return coloring

    # Run all strategies and pick best
    candidates = []
    for strat in (dsatur, rlf, smallest_last):
        try:
            col = strat()
            if is_valid(col):
                candidates.append(col)
        except Exception:
            continue

    if not candidates:
        # fallback: greedy random order
        order = list(range(n))
        random.shuffle(order)
        coloring = [-1] * n
        for u in order:
            mask = 0
            for v in graph[u]:
                if coloring[v] != -1:
                    mask |= 1 << coloring[v]
            coloring[u] = first_fit(mask)
        candidates.append(coloring)

    # select candidate with fewest colors
    best = min(candidates, key=num_colors)
    k = num_colors(best)

    # Kempe chain color reduction
    def eliminate_color_class(coloring, target_color):
        # vertices with target color
        verts = [u for u in range(n) if coloring[u] == target_color]
        if not verts:
            return coloring, True  # already eliminated
        # try to recolor each vertex
        for v in verts:
            # try direct reassignment to lower color
            for c in range(target_color):
                conflict = False
                for nb in graph[v]:
                    if coloring[nb] == c:
                        conflict = True
                        break
                if not conflict:
                    coloring[v] = c
                    break
            else:
                # try Kempe chain swap with each lower color
                for c in range(target_color):
                    # BFS to find Kempe chain of colors c and target_color containing v
                    from collections import deque
                    visited = [False] * n
                    q = deque([v])
                    visited[v] = True
                    component = []
                    while q:
                        u = q.popleft()
                        component.append(u)
                        for nb in graph[u]:
                            if not visited[nb] and (coloring[nb] == c or coloring[nb] == target_color):
                                visited[nb] = True
                                q.append(nb)
                    # check if swapping c and target_color in component is valid
                    # after swap, no adjacent same color
                    valid_swap = True
                    for u in component:
                        new_color = c if coloring[u] == target_color else target_color
                        for nb in graph[u]:
                            if coloring[nb] == new_color:
                                valid_swap = False
                                break
                        if not valid_swap:
                            break
                    if valid_swap:
                        # perform swap
                        for u in component:
                            if coloring[u] == c:
                                coloring[u] = target_color
                            else:
                                coloring[u] = c
                        # now v has color c
                        break
                else:
                    # could not recolor v
                    return coloring, False
        # all vertices recolored, eliminate target color
        # remap colors > target_color down by 1
        for u in range(n):
            if coloring[u] > target_color:
                coloring[u] -= 1
        return coloring, True

    # iteratively try to eliminate highest color class
    improved = True
    while improved and k > 0:
        improved = False
        # try to eliminate color k-1
        new_coloring, success = eliminate_color_class(best[:], k-1)
        if success:
            best = new_coloring
            k = num_colors(best)
            improved = True

    # final validation and compact colors
    # ensure colors are 0..k-1
    color_map = {}
    next_color = 0
    for u in range(n):
        c = best[u]
        if c not in color_map:
            color_map[c] = next_color
            next_color += 1
        best[u] = color_map[c]
    return best

