def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []
    # Detect input format: adjacency matrix or adjacency list
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True
    # Build adjacency list and bitmask representation
    adj_list = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for u in range(n):
            for v in range(n):
                if adj[u][v]:
                    adj_list[u].append(v)
                    bit_adj[u] |= (1 << v)
    else:
        for u in range(n):
            for v in adj[u]:
                if 0 <= v < n:
                    adj_list[u].append(v)
                    bit_adj[u] |= (1 << v)
    # Helper: proper coloring check
    def is_proper(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in adj_list[u]:
                if cu == coloring[v]:
                    return False
        return True
    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0
    # Helper: greedy coloring with given order
    def greedy_color(order):
        coloring = [-1] * n
        for u in order:
            used = 0
            for v in adj_list[u]:
                c = coloring[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            coloring[u] = c
        return coloring
    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        saturated = [0] * n  # bitmask of colors used by neighbors
        uncolored = set(range(n))
        # Precompute degrees for tie-breaking
        degrees = [len(adj_list[u]) for u in range(n)]
        while uncolored:
            # Select vertex with max saturation degree, tie-break by degree, then random
            best = -1
            best_sat = -1
            best_deg = -1
            for u in uncolored:
                sat = saturated[u].bit_count()
                deg = degrees[u]
                if sat > best_sat or (sat == best_sat and deg > best_deg) or (sat == best_sat and deg == best_deg and random.random() < 0.5):
                    best_sat = sat
                    best_deg = deg
                    best = u
            u = best
            # Assign smallest available color
            avail = (~saturated[u]) & ((1 << n) - 1)  # colors 0..n-1
            c = (avail & -avail).bit_length() - 1 if avail else 0
            coloring[u] = c
            uncolored.remove(u)
            # Update saturation of neighbors
            for v in adj_list[u]:
                if v in uncolored:
                    saturated[v] |= (1 << c)
        return coloring
    # Helper: RLF (Recursive Largest First)
    def rlf():
        coloring = [-1] * n
        uncolored = set(range(n))
        color = 0
        while uncolored:
            # Build maximal independent set for this color
            # Start with vertex of max degree in uncolored subgraph
            # Compute degrees in induced subgraph G[uncolored]
            deg_in_uncolored = {u: 0 for u in uncolored}
            for u in uncolored:
                for v in adj_list[u]:
                    if v in uncolored:
                        deg_in_uncolored[u] += 1
            # Choose v1 with max degree
            v1 = max(uncolored, key=lambda u: deg_in_uncolored[u])
            S = {v1}
            # Partition remaining uncolored into U (not adj to S) and W (adj to S)
            U = uncolored - {v1} - set()
            for v in adj_list[v1]:
                if v in U:
                    U.remove(v)
            W = set()
            for v in adj_list[v1]:
                if v in uncolored and v not in S:
                    W.add(v)
            # Now U are vertices not adjacent to any in S (eligible)
            # Actually, we need to recompute U properly: vertices in uncolored not adjacent to any in S
            U = {u for u in uncolored if u not in S and all(u not in adj_list[s] for s in S)}
            # While U not empty, add vertex with max neighbors in W
            while U:
                # Select u in U maximizing |N(u) ∩ W|
                best_u = -1
                best_score = -1
                best_deg_in_U = float('inf')
                for u in U:
                    # count neighbors in W
                    score = 0
                    for v in adj_list[u]:
                        if v in W:
                            score += 1
                    # deg in G[U]
                    deg_u = 0
                    for v in adj_list[u]:
                        if v in U:
                            deg_u += 1
                    if score > best_score or (score == best_score and deg_u < best_deg_in_U) or (score == best_score and deg_u == best_deg_in_U and random.random() < 0.5):
                        best_score = score
                        best_deg_in_U = deg_u
                        best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for v in adj_list[u]:
                    if v in U:
                        U.remove(v)
                        W.add(v)
            # Assign color to all in S
            for u in S:
                coloring[u] = color
            uncolored -= S
            color += 1
        return coloring
    # Helper: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute core decomposition ordering (smallest last)
        # Copy degrees
        degrees = [len(adj_list[u]) for u in range(n)]
        # Bin vertices by degree
        max_deg = max(degrees) if n > 0 else 0
        bins = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            d = degrees[u]
            bins[d].append(u)
        # Pointer to current non-empty bin
        ptr = 0
        order = []
        # We'll maintain a list of deleted vertices
        deleted = [False] * n
        # For each vertex, we need to update degrees of neighbors when deleted
        # We'll simulate peeling
        for _ in range(n):
            # Find next non-empty bin
            while ptr <= max_deg and not bins[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            u = bins[ptr].pop()
            while deleted[u]:
                if not bins[ptr]:
                    ptr += 1
                    while ptr <= max_deg and not bins[ptr]:
                        ptr += 1
                    if ptr > max_deg:
                        break
                    u = bins[ptr].pop()
                else:
                    break
            if deleted[u]:
                continue
            deleted[u] = True
            order.append(u)
            # Decrease degree of neighbors
            for v in adj_list[u]:
                if not deleted[v]:
                    d = degrees[v]
                    degrees[v] -= 1
                    if d < len(bins):
                        bins[d].append(v)
        # Reverse order for coloring
        order.reverse()
        return greedy_color(order)
    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        c1 = dsatur()
        if is_proper(c1):
            candidates.append(c1)
    except Exception:
        pass
    # RLF
    try:
        c2 = rlf()
        if is_proper(c2):
            candidates.append(c2)
    except Exception:
        pass
    # Smallest-Last
    try:
        c3 = smallest_last()
        if is_proper(c3):
            candidates.append(c3)
    except Exception:
        pass
    # Fallback: greedy by degree order
    try:
        order = sorted(range(n), key=lambda u: len(adj_list[u]), reverse=True)
        c4 = greedy_color(order)
        if is_proper(c4):
            candidates.append(c4)
    except Exception:
        pass
    # If no candidates, assign all zeros (only works for edgeless)
    if not candidates:
        coloring = [0] * n
        if is_proper(coloring):
            candidates.append(coloring)
        else:
            # last resort: assign unique colors
            candidates.append(list(range(n)))
    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    # Ensure colors are consecutive starting from 0
    used = set(best)
    mapping = {}
    if used:
        sorted_used = sorted(used)
        for i, c in enumerate(sorted_used):
            mapping[c] = i
        best = [mapping[c] for c in best]
    return best

import math
