def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Convert to adjacency list and compute degree
    if len(adj) > 0 and len(adj[0]) == n and all(
        isinstance(x, int) and x in (0, 1) for row in adj for x in row
    ):
        graph = [[] for _ in range(n)]
        for u in range(n):
            for v in range(n):
                if adj[u][v] == 1:
                    graph[u].append(v)
    else:
        graph = [list(neighbors) for neighbors in adj]

    degree = [len(graph[i]) for i in range(n)]

    # Helper: check if coloring is valid
    def is_valid(coloring):
        for u in range(n):
            cu = coloring[u]
            for v in graph[u]:
                if cu == coloring[v]:
                    return False
        return True

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: convert coloring to zero-based consecutive
    def compact_colors(coloring):
        if not coloring:
            return coloring
        unique = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique:
                unique[c] = next_color
                next_color += 1
            coloring[i] = unique[c]
        return coloring

    # DSATUR with degree tie-breaking
    def dsatur():
        coloring = [-1] * n
        saturated = [set() for _ in range(n)]
        uncolored = set(range(n))
        while uncolored:
            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(
                uncolored,
                key=lambda x: (
                    len(saturated[x]),
                    sum(1 for nb in graph[x] if nb in uncolored),
                    -x  # to break ties by lower index if needed, but we use random later
                )
            )
            # Find smallest available color
            used = saturated[v]
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
            uncolored.remove(v)
            # Update saturation of uncolored neighbors
            for nb in graph[v]:
                if nb in uncolored:
                    saturated[nb].add(c)
        return coloring

    # RLF: Recursive Largest First (independent set extraction)
    def rlf():
        coloring = [-1] * n
        color = 0
        uncolored = set(range(n))
        while uncolored:
            # Build independent set for this color
            independent_set = set()
            # Start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for nb in graph[x] if nb in uncolored))
            independent_set.add(v)
            # Partition: U = not adjacent to any in independent_set, W = adjacent to at least one
            U = {u for u in uncolored if u not in independent_set and
                 all(nb not in independent_set for nb in graph[u])}
            W = uncolored - independent_set - U
            while U:
                # Select u in U with max neighbors in W, tie-break by min degree in U
                u = max(
                    U,
                    key=lambda x: (
                        sum(1 for nb in graph[x] if nb in W),
                        -sum(1 for nb in graph[x] if nb in U),  # min degree in U -> negative for max
                        -x
                    )
                )
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for nb in graph[u]:
                    if nb in U:
                        U.remove(nb)
                        W.add(nb)
            # Assign color to independent_set
            for v in independent_set:
                coloring[v] = color
                uncolored.remove(v)
            color += 1
        return coloring

    # Smallest-Last (Matula & Beck) ordering + greedy
    def smallest_last():
        # Compute degeneracy ordering
        order = []
        degrees = degree[:]
        remaining = set(range(n))
        # Buckets for degrees
        max_deg = max(degrees) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            d = degrees[v]
            if d < len(buckets):
                buckets[d].append(v)
            else:
                # extend buckets if needed (should not happen)
                buckets.extend([[] for _ in range(d - len(buckets) + 1)])
                buckets[d].append(v)
        # Pointer to current min non-empty bucket
        min_deg = 0
        while remaining:
            # Find next non-empty bucket
            while min_deg < len(buckets) and not buckets[min_deg]:
                min_deg += 1
            if min_deg >= len(buckets):
                break  # should not happen
            v = buckets[min_deg].pop()
            if v not in remaining:
                continue
            order.append(v)
            remaining.remove(v)
            # Update degrees of neighbors
            for nb in graph[v]:
                if nb in remaining:
                    d = degrees[nb]
                    # remove nb from bucket d
                    if nb in buckets[d]:
                        buckets[d].remove(nb)
                    degrees[nb] -= 1
                    d_new = degrees[nb]
                    # ensure bucket exists
                    while d_new >= len(buckets):
                        buckets.append([])
                    buckets[d_new].append(nb)
            # update min_deg if needed
            if degrees[v] < min_deg:
                min_deg = degrees[v]
        # Color in reverse order
        coloring = [-1] * n
        for v in reversed(order):
            used = {coloring[nb] for nb in graph[v] if coloring[nb] != -1}
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        return coloring

    # Kempe chain swap for (a,b)
    def kempe_swap(coloring, a, b, v):
        # Returns new coloring if swap is performed, else None
        # Find the b-Kempe chain containing v in colors a and b
        stack = [v]
        visited = set()
        component = set()
        while stack:
            u = stack.pop()
            if u in visited:
                continue
            visited.add(u)
            if coloring[u] == a or coloring[u] == b:
                component.add(u)
                for nb in graph[u]:
                    if nb not in visited and (coloring[nb] == a or coloring[nb] == b):
                        stack.append(nb)
        # Check if swapping is safe: no neighbor of component has color a (if we are moving v from b to a) 
        # Actually, we want to swap a and b in the component. It is always safe as long as we only swap within the component.
        # But we want to free color b for v? Actually, we are trying to recolor v from b to a via swap.
        # After swap, v will have color a (if it was b) or b (if it was a). We assume v is colored b.
        # We want to move v to color a, so we swap a and b in the component containing v.
        # This is valid if no vertex in the component has a neighbor outside the component with color a (if we are introducing a) 
        # or color b (if we are introducing b). Actually, Kempe swap is always valid for the two colors.
        # However, we must ensure that after swap, we don't create conflict. The swap preserves validity.
        # So we can always perform the swap, but we want to know if it helps to free color b.
        # We are trying to eliminate color b by moving v to a. After swap, v becomes a (if it was b) and some a's become b.
        # So the number of vertices colored b may increase or decrease.
        # Actually, we want to know if after swap, v is no longer colored b (i.e., it becomes a) and we don't introduce new b's that are hard to remove.
        # But for the purpose of eliminating a color class, we just want to recolor v to a different color.
        # We will use this function to attempt to swap so that v can take color a.
        # We assume v is colored b and we want to try to make it a.
        if coloring[v] != b:
            # We expect v to be b, but if not, we can still try to swap if it's a and we want b? 
            # For simplicity, we only call this when we want to move v from b to a.
            return None
        # Perform swap: a<->b in component
        new_coloring = coloring[:]
        for u in component:
            if new_coloring[u] == a:
                new_coloring[u] = b
            elif new_coloring[u] == b:
                new_coloring[u] = a
        return new_coloring

    # Attempt to eliminate the last color class using Kempe chains
    def reduce_colors(coloring):
        if not coloring:
            return coloring
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # Try to eliminate color k-1
        target_color = k - 1
        vertices = [v for v in range(n) if coloring[v] == target_color]
        # Try multiple rounds
        for _ in range(2):  # limited rounds for speed
            made_progress = False
            for v in vertices[:]:  # iterate over copy
                if coloring[v] != target_color:
                    continue
                # Try direct reassignment to a lower color
                used = {coloring[nb] for nb in graph[v]}
                for c in range(target_color):
                    if c not in used:
                        coloring[v] = c
                        made_progress = True
                        break
                if made_progress:
                    break
                # Try Kempe chains with each lower color
                for c in range(target_color):
                    # Try to swap (target_color, c) chain containing v
                    new_col = kempe_swap(coloring, target_color, c, v)
                    if new_col is not None:
                        # Check if v is no longer target_color
                        if new_col[v] != target_color:
                            coloring[:] = new_col
                            made_progress = True
                            break
                if made_progress:
                    break
            if not made_progress:
                break
        # Compact colors
        return compact_colors(coloring)

    # Generate candidates
    candidates = []
    try:
        c1 = dsatur()
        if is_valid(c1):
            candidates.append(c1)
    except:
        pass
    try:
        c2 = rlf()
        if is_valid(c2):
            candidates.append(c2)
    except:
        pass
    try:
        c3 = smallest_last()
        if is_valid(c3):
            candidates.append(c3)
    except:
        pass

    # If no candidate, fallback to greedy
    if not candidates:
        coloring = [-1] * n
        for v in range(n):
            used = {coloring[nb] for nb in graph[v] if coloring[nb] != -1}
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        candidates.append(coloring)

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    best = compact_colors(best)

    # Iterative reduction
    for _ in range(3):  # limited rounds
        new_best = reduce_colors(best[:])
        if num_colors(new_best) < num_colors(best):
            best = new_best
        else:
            break

    # Final validation and compact
    if not is_valid(best):
        # Fallback to greedy ordering by degree
        order = sorted(range(n), key=lambda x: degree[x], reverse=True)
        coloring = [-1] * n
        for v in order:
            used = {coloring[nb] for nb in graph[v] if coloring[nb] != -1}
            c = 0
            while c in used:
                c += 1
            coloring[v] = c
        best = compact_colors(coloring)

    return best

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect if adjacency matrix or list
    if len(adj[0]) == n and all(x in (0, 1) for row in adj for x in row):
        # Adjacency matrix
        bit_adj = [0] * n
        for u in range(n):
            for v in range(n):
                if adj[u][v]:
                    bit_adj[u] |= (1 << v)
    else:
        # Adjacency list
        bit_adj = [0] * n
        for u in range(n):
            for v in adj[u]:
                bit_adj[u] |= (1 << v)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in range(n):
                if (bit_adj[u] >> v) & 1 and color[v] != -1:
                    used |= (1 << color[v])
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Helper: compute number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in range(n):
                if (bit_adj[u] >> v) & 1 and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: compact colors to 0..k-1
    def compact_colors(coloring):
        mapping = {}
        next_color = 0
        for c in coloring:
            if c not in mapping:
                mapping[c] = next_color
                next_color += 1
        return [mapping[c] for c in coloring]

    # Strategy 1: DSATUR with degree tie-breaking
    def dsatur():
        color = [-1] * n
        # saturation: number of distinct colors in neighborhood
        sat = [0] * n
        # degree in uncolored subgraph (for tie-breaking)
        uncolored_deg = [bin(bit_adj[u]).count("1") for u in range(n)]
        uncolored = set(range(n))

        for _ in range(n):
            # select vertex with max saturation, tie-break by max degree in uncolored, then random
            candidates = []
            max_sat = -1
            for u in uncolored:
                if sat[u] > max_sat:
                    max_sat = sat[u]
                    candidates = [u]
                elif sat[u] == max_sat:
                    candidates.append(u)
            # tie-break by degree in uncolored subgraph
            max_deg = -1
            for u in candidates:
                if uncolored_deg[u] > max_deg:
                    max_deg = uncolored_deg[u]
                    best = u
                elif uncolored_deg[u] == max_deg:
                    if random.random() < 0.5:  # random tie-break
                        best = u
            # assign smallest available color
            used = 0
            for v in range(n):
                if (bit_adj[best] >> v) & 1 and color[v] != -1:
                    used |= (1 << color[v])
            c = 0
            while used & (1 << c):
                c += 1
            color[best] = c
            uncolored.remove(best)
            # update saturation and uncolored degree for neighbors
            for v in range(n):
                if (bit_adj[best] >> v) & 1:
                    if color[v] == -1:  # if neighbor uncolored
                        sat[v] += 1  # new color appears in neighborhood
                        uncolored_deg[v] -= 1  # one less uncolored neighbor
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build independent set for color c
            # start with vertex of max degree in uncolored subgraph
            max_deg = -1
            v0 = -1
            for u in uncolored:
                deg = 0
                for w in uncolored:
                    if (bit_adj[u] >> w) & 1:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v0 = u
            S = {v0}
            # U: vertices not adjacent to any in S (eligible)
            # W: vertices adjacent to at least one in S (ineligible)
            U = set()
            W = set()
            for u in uncolored:
                if u == v0:
                    continue
                adjacent = False
                for s in S:
                    if (bit_adj[u] >> s) & 1:
                        adjacent = True
                        break
                if adjacent:
                    W.add(u)
                else:
                    U.add(u)
            # greedily add to S from U
            while U:
                # select u in U with max |N(u) ∩ W|, tie-break by min degree in G[U]
                best_u = -1
                max_nw = -1
                min_deg_u = float('inf')
                for u in U:
                    # count neighbors in W
                    nw = 0
                    for w in W:
                        if (bit_adj[u] >> w) & 1:
                            nw += 1
                    # degree in U
                    deg_u = 0
                    for v in U:
                        if (bit_adj[u] >> v) & 1:
                            deg_u += 1
                    if nw > max_nw or (nw == max_nw and deg_u < min_deg_u):
                        max_nw = nw
                        min_deg_u = deg_u
                        best_u = u
                S.add(best_u)
                U.remove(best_u)
                # move neighbors of best_u from U to W
                for v in list(U):
                    if (bit_adj[best_u] >> v) & 1:
                        U.remove(v)
                        W.add(v)
            # assign color c to all in S
            for u in S:
                color[u] = c
                uncolored.remove(u)
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # compute degeneracy ordering
        degree = [bin(bit_adj[u]).count("1") for u in range(n)]
        # buckets for degree
        max_deg = max degree if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[degree[u]].append(u)
        # track current degree and position
        pos = [0] * n
        for d in range(max_deg + 1):
            for i, u in enumerate(buckets[d]):
                pos[u] = i
        # ordering stack
        order = []
        current_deg = degree[:]
        # pointer to non-empty bucket
        ptr = 0
        for _ in range(n):
            # find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            u = buckets[ptr].pop()
            order.append(u)
            # update neighbors
            for v in range(n):
                if (bit_adj[u] >> v) & 1 and pos[v] > pos[u]:  # v not yet removed
                    # remove edge (u,v)
                    d = current_deg[v]
                    buckets[d].pop(pos[v])
                    current_deg[v] -= 1
                    d_new = current_deg[v]
                    buckets[d_new].append(v)
                    pos[v] = len(buckets[d_new]) - 1
                    if d_new < ptr:
                        ptr = d_new
        # color in reverse order
        return greedy_color(reversed(order))

    # Generate candidate colorings
    candidates = []
    # DSATUR
    try:
        col1 = dsatur()
        if is_valid(col1):
            candidates.append(col1)
    except:
        pass
    # RLF
    try:
        col2 = rlf()
        if is_valid(col2):
            candidates.append(col2)
    except:
        pass
    # Smallest-Last
    try:
        col3 = smallest_last()
        if is_valid(col3):
            candidates.append(col3)
    except:
        pass
    # Fallback: Welsh-Powell (degree order)
    try:
        order = sorted(range(n), key=lambda u: bin(bit_adj[u]).count("1"), reverse=True)
        col4 = greedy_color(order)
        if is_valid(col4):
            candidates.append(col4)
    except:
        pass
    # Fallback: random order
    try:
        order = list(range(n))
        random.shuffle(order)
        col5 = greedy_color(order)
        if is_valid(col5):
            candidates.append(col5)
    except:
        pass

    # Select best candidate (fewest colors)
    if not candidates:
        # last resort: assign each vertex a unique color
        best_color = list(range(n))
    else:
        best_color = min(candidates, key=num_colors)

    # Compact colors
    best_color = compact_colors(best_color)

    # Iterative Kempe chain color reduction
    def kempe_reduce(coloring):
        k = num_colors(coloring)
        if k <= 1:
            return coloring
        # try to eliminate color classes from highest to lowest
        for target_color in range(k-1, 0, -1):
            # vertices with target_color
            verts = [u for u in range(n) if coloring[u] == target_color]
            if not verts:
                continue
            # try to recolor each vertex in this class
            removed = True
            while removed and verts:
                removed = False
                # try direct reassignment to a lower color
                for u in verts[:]:
                    used = 0
                    for v in range(n):
                        if (bit_adj[u] >> v) & 1 and coloring[v] != -1:
                            used |= (1 << coloring[v])
                    for c in range(target_color):
                        if not (used & (1 << c)):
                            # move u to color c
                            coloring[u] = c
                            verts.remove(u)
                            removed = True
                            break
                if not removed:
                    # try Kempe chain swaps
                    for u in verts[:]:
                        for c in range(target_color):
                            # check if u can be swapped via (target_color, c) Kempe chain
                            # BFS to find component containing u in subgraph of colors target_color and c
                            from collections import deque
                            visited = [False] * n
                            queue = deque([u])
                            visited[u] = True
                            component = []
                            while queue:
                                x = queue.popleft()
                                component.append(x)
                                for y in range(n):
                                    if (bit_adj[x] >> y) & 1 and not visited[y]:
                                        if coloring[y] == target_color or coloring[y] == c:
                                            visited[y] = True
                                            queue.append(y)
                            # check if swapping this component is safe: no neighbor outside component has color c after swap
                            # after swap, vertices in component of color target_color become c, and vice versa
                            # we are moving u from target_color to c, so we need that no neighbor of any vertex in component
                            # that is colored c (and will become target_color) conflicts
                            # actually, we only care that after swap, no adjacent vertices share color
                            # since we only swap two colors, it's safe if the component does not contain a vertex
                            # adjacent to a vertex of color c outside the component (because that would become target_color and conflict)
                            # but standard Kempe chain swap is always safe for maintaining proper coloring
                            # however, we want to free color target_color for u, i.e., after swap, u becomes c
                            # and we want that no vertex in the component that was color c becomes target_color and is adjacent to a vertex of color target_color outside?
                            # Actually, the swap preserves validity. The goal is to make it possible to recolor u to c without increasing colors.
                            # But if we swap, u becomes c, and some vertices in component that were c become target_color.
                            # We want that after swap, no vertex has color target_color? Not necessarily.
                            # We are trying to eliminate color target_color. So we want that after processing, no vertex remains with target_color.
                            # So we need that the component does not contain any vertex that, after swap, remains target_color? 
                            # Actually, after swap, vertices in component that were target_color become c, and those that were c become target_color.
                            # So the set of vertices with color target_color after swap is: 
                            #   (original target_color vertices not in component) union (original c vertices in component)
                            # We want this set to be empty eventually.
                            # For our purpose, we try to move u out of target_color. After swap, u is no longer target_color.
                            # So we can assign u to c via swap and remove it from target_color class.
                            # The swap is valid and reduces the size of target_color class by at least 1 (if the component contains at least one vertex of target_color, which it does: u).
                            # So we perform the swap and remove u from verts.
                            # Perform swap: flip colors in component
                            for x in component:
                                if coloring[x] == target_color:
                                    coloring[x] = c
                                elif coloring[x] == c:
                                    coloring[x] = target_color
                            verts.remove(u)
                            removed = True
                            break
                        if removed:
                            break
            if not verts:  # all vertices recolored from target_color
                # compact colors down by one
                mapping = {}
                next_color = 0
                for col in coloring:
                    if col not in mapping:
                        if col == target_color:
                            continue  # skip this color
                        mapping[col] = next_color
                        next_color += 1
                # remap
                new_coloring = [0] * n
                for i in range(n):
                    col = coloring[i]
                    if col == target_color:
                        # find a color to assign? Actually, we removed the color, so we need to map
                        # but we already removed all vertices of this color, so this should not happen
                        # safety: assign to 0
                        new_coloring[i] = 0
                    else:
                        new_coloring[i] = mapping[col]
                coloring = new_coloring
                k = num_colors(coloring)
                if k <= 1:
                    break
                # restart reduction from new highest color
                break  # break to restart while loop with new k
        return coloring

    # Apply Kempe reduction
    best_color = kempe_reduce(best_color)
    # Final compact and validate
    best_color = compact_colors(best_color)
    if not is_valid(best_color):
        # fallback to DSATUR if something went wrong
        best_color = dsatur()
        best_color = compact_colors(best_color)
    return best_color

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Detect adjacency matrix or list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Convert to adjacency list and bitmask for fast operations
    neighbors = [[] for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].append(j)
                    bit_adj[i] |= (1 << j)

    # Helper: greedy coloring with given order
    def greedy_color(order):
        color = [-1] * n
        used_colors = [0] * n  # bitmask of colors used by neighbors
        for v in order:
            # find smallest color not used by neighbors
            c = 0
            while used_colors[v] & (1 << c):
                c += 1
            color[v] = c
            # update neighbors
            for u in neighbors[v]:
                used_colors[u] |= (1 << c)
        return color

    # Helper: number of colors used
    def num_colors(coloring):
        return max(coloring) + 1 if coloring else 0

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Strategy 1: DSATUR with bitmask optimization
    def dsatur():
        color = [-1] * n
        # saturation: bitmask of colors used by neighbors
        saturation = [0] * n
        # degree in uncolored subgraph
        uncolored_deg = [len(neighbors[i]) for i in range(n)]
        uncolored = set(range(n))
        for _ in range(n):
            # select vertex with max saturation, then max degree, then random
            v = -1
            max_sat = -1
            max_deg = -1
            for u in uncolored:
                sat = saturation[u].bit_count()
                deg = uncolored_deg[u]
                if sat > max_sat or (sat == max_sat and deg > max_deg) or (sat == max_sat and deg == max_deg and (v == -1 or random.random() < 0.5)):
                    max_sat = sat
                    max_deg = deg
                    v = u
            # assign smallest available color
            c = 0
            while saturation[v] & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
            # update neighbors
            for u in neighbors[v]:
                if u in uncolored:
                    saturation[u] |= (1 << c)
                    uncolored_deg[u] -= 1
        return color

    # Strategy 2: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # build independent set for color c
            # start with vertex of max degree in uncolored subgraph
            v = max(uncolored, key=lambda x: sum(1 for y in neighbors[x] if y in uncolored))
            independent_set = {v}
            # U: vertices not adjacent to any in independent_set
            # W: vertices adjacent to at least one in independent_set
            U = {u for u in uncolored if u != v and all((bit_adj[u] & (1 << w)) == 0 for w in independent_set)}
            W = {u for u in uncolored if u not in independent_set and u not in U}
            while U:
                # select u in U with max |N(u) ∩ W|
                u = max(U, key=lambda x: sum(1 for y in neighbors[x] if y in W))
                # tie-break: min degree in G[U]
                independent_set.add(u)
                U.remove(u)
                # move neighbors of u in U to W
                for y in neighbors[u]:
                    if y in U:
                        U.remove(y)
                        W.add(y)
            # assign color c to independent_set
            for v in independent_set:
                color[v] = c
                uncolored.remove(v)
            c += 1
        return color

    # Strategy 3: Smallest-Last ordering
    def smallest_last():
        # core decomposition to get ordering
        deg = [len(neighbors[i]) for i in range(n)]
        order = []
        remaining = set(range(n))
        # bucket sort by degree
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for v in range(n):
            buckets[deg[v]].append(v)
        # maintain pointer to non-empty bucket
        ptr = 0
        for _ in range(n):
            # find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            v = buckets[ptr].pop()
            order.append(v)
            remaining.remove(v)
            # update degrees of neighbors
            for u in neighbors[v]:
                if u in remaining:
                    d = deg[u]
                    deg[u] -= 1
                    if d < len(buckets):
                        buckets[d].append(u)
                    else:
                        # extend buckets if needed (should not happen)
                        buckets.extend([[] for _ in range(d - len(buckets) + 1)])
                        buckets[d].append(u)
        # color in reverse order
        return greedy_color(order[::-1])

    # Generate candidate colorings
    candidates = []
    try:
        candidates.append(dsatur())
    except:
        pass
    try:
        candidates.append(rlf())
    except:
        pass
    try:
        candidates.append(smallest_last())
    except:
        pass
    # Also try greedy with degree ordering
    try:
        order_deg = sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True)
        candidates.append(greedy_color(order_deg))
    except:
        pass
    # Try greedy with random order a few times
    for _ in range(2):
        try:
            order_rand = list(range(n))
            random.shuffle(order_rand)
            candidates.append(greedy_color(order_rand))
        except:
            pass

    # Select best candidate (fewest colors)
    best_coloring = None
    best_k = float('inf')
    for col in candidates:
        if is_valid(col):
            k = num_colors(col)
            if k < best_k:
                best_k = k
                best_coloring = col
    if best_coloring is None:
        # fallback: greedy with natural order
        best_coloring = greedy_color(list(range(n)))
        best_k = num_colors(best_coloring)

    # Kempe chain-based color reduction
    def kempe_reduce(coloring):
        # make coloring consecutive
        def renormalize(col):
            mapping = {}
            next_c = 0
            for v in range(n):
                c = col[v]
                if c not in mapping:
                    mapping[c] = next_c
                    next_c += 1
                col[v] = mapping[c]
            return col

        coloring = renormalize(coloring[:])
        k = num_colors(coloring)
        improved = True
        while improved and k > 1:
            improved = False
            # find smallest color class
            color_classes = [[] for _ in range(k)]
            for v in range(n):
                color_classes[coloring[v]].append(v)
            # try to eliminate color k-1
            target_color = k - 1
            if not color_classes[target_color]:
                # should not happen after renormalize
                break
            # try to recolor each vertex in target_color
            for v in color_classes[target_color][:]:  # copy as we may modify
                # try direct reassignment to a lower color
                used = [False] * k
                for u in neighbors[v]:
                    used[coloring[u]] = True
                for c in range(target_color):
                    if not used[c]:
                        # move v to color c
                        coloring[v] = c
                        improved = True
                        break
                if improved:
                    break
                # try Kempe chains with each lower color
                for c in range(target_color):
                    # if v already has color c from direct reassignment, skip
                    if coloring[v] == c:
                        break
                    # BFS to find (c, target_color) Kempe chain containing v
                    from collections import deque
                    visited = [False] * n
                    queue = deque([v])
                    visited[v] = True
                    component = []
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        for y in neighbors[x]:
                            if not visited[y] and (coloring[y] == c or coloring[y] == target_color):
                                visited[y] = True
                                queue.append(y)
                    # check if we can swap: no neighbor of component has color c outside component
                    can_swap = True
                    for x in component:
                        for y in neighbors[x]:
                            if not visited[y] and coloring[y] == c:
                                can_swap = False
                                break
                        if not can_swap:
                            break
                    if can_swap:
                        # perform swap
                        for x in component:
                            if coloring[x] == c:
                                coloring[x] = target_color
                            else:
                                coloring[x] = c
                        improved = True
                        break
                if improved:
                    break
            if improved:
                # renormalize and repeat
                coloring = renormalize(coloring)
                k = num_colors(coloring)
            else:
                break
        return coloring

    best_coloring = kempe_reduce(best_coloring)
    # final validation and renormalize
    if not is_valid(best_coloring):
        # last resort: greedy with DSATUR order
        best_coloring = dsatur()
    best_coloring = renormalize(best_coloring) if 'renormalize' in locals() else best_coloring
    return best_coloring

