                    for v in graph[u]:
                        if v in uncolored:
                            deg += 1
                    if deg > max_deg:
                        max_deg = deg
                        best_u = u
                u = best_u
            else:
                u = candidates[0]

            # Assign smallest available color
            used = sat[u]
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c

            # Update saturation of uncolored neighbors
            for v in graph[u]:
                if color[v] == -1:  # v is uncolored
                    sat[v] |= (1 << c)

            uncolored.remove(u)
        return color

    # 2. RLF (Recursive Largest First) independent set extraction
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build independent set for color c
            S = set()
            # Start with vertex of max degree in uncolored subgraph
            max_deg = -1
            v0 = None
            for u in uncolored:
                deg = 0
                for v in graph[u]:
                    if v in uncolored:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v0 = u
            if v0 is None:
                break  # should not happen
            S.add(v0)
            # U: vertices not adjacent to S (eligible), W: adjacent to S (ineligible)
            U = uncolored - {v0}
            W = set()
            for v in graph[v0]:
                if v in U:
                    U.remove(v)
                    W.add(v)
            # While there are eligible vertices
            while U:
                # Select u in U with max |N(u) ∩ W|
                best_u = None
                max_w_neighbors = -1
                min_deg_in_U = float('inf')
                for u in U:
                    # count neighbors in W
                    w_count = 0
                    for v in graph[u]:
                        if v in W:
                            w_count += 1
                    # tie-break: min degree in U
                    deg_in_U = 0
                    for v in graph[u]:
                        if v in U:
                            deg_in_U += 1
                    if w_count > max_w_neighbors or (w_count == max_w_neighbors and deg_in_U < min_deg_in_U):
                        max_w_neighbors = w_count
                        min_deg_in_U = deg_in_U
                        best_u = u
                # Add best_u to S, move its U-neighbors to W
                S.add(best_u)
                U.remove(best_u)
                for v in graph[best_u]:
                    if v in U:
                        U.remove(v)
                        W.add(v)
            # Assign color c to all in S
            for u in S:
                color[u] = c
            # Remove S from uncolored
            uncolored -= S
            c += 1
        return color

    # 3. Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute degeneracy ordering
        order = []
        remaining = set(range(n))
        deg = [len(graph[u]) for u in range(n)]
        # buckets for degrees
        max_deg = max(deg) if n > 0 else 0
        buckets = [[] for _ in range(max_deg + 1)]
        for u in range(n):
            buckets[deg[u]].append(u)
        # pointer to current min degree
        ptr = 0
        while remaining:
            # find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break
            u = buckets[ptr].pop()
            if u not in remaining:
                continue
            order.append(u)
            remaining.remove(u)
            # update neighbors
            for v in graph[u]:
                if v in remaining:
                    d = deg[v]
                    # remove v from bucket d
                    if v in buckets[d]:
                        buckets[d].remove(v)
                    deg[v] -= 1
                    dnew = deg[v]
                    if dnew >= len(buckets):
                        buckets.extend([[] for _ in range(dnew - len(buckets) + 1)])
                    buckets[dnew].append(v)
        # color in reverse order
        return greedy_coloring(order[::-1])

    # 4. Welsh-Powell: sort by degree descending
    def welsh_powell():
        order = sorted(range(n), key=lambda u: len(graph[u]), reverse=True)
        return greedy_coloring(order)

    # Generate candidate colorings
    candidates = []
    for func in [dsatur, rlf, smallest_last, welsh_powell]:
        try:
            col = func()
            if is_valid(col):
                candidates.append(col)
        except Exception:
            continue

    # Also try random orderings a few times
    for _ in range(10):
        order = list(range(n))
        random.shuffle(order)
        col = greedy_coloring(order)
        if is_valid(col):
            candidates.append(col)

    # Select best candidate (fewest colors)
    for col in candidates:
        k = count_colors(col)
        if k < best_k:
            best_k = k
            best_coloring = col

    # Fallback: greedy on natural order
    if best_coloring is None:
        best_coloring = greedy_coloring(list(range(n)))
        best_k = count_colors(best_coloring)

    # 5. Kempe chain-based color reduction
    def eliminate_color_class(coloring, target_color):
        # Try to recolor all vertices of target_color to lower colors
        # Returns new coloring with target_color eliminated, or None if not possible
        vertices = [u for u in range(n) if coloring[u] == target_color]
        if not vertices:
            return coloring  # already eliminated
        # Try direct reassignment first
        new_coloring = coloring[:]
        for u in vertices:
            used = 0
            for v in graph[u]:
                c = new_coloring[v]
                if c != -1:
                    used |= (1 << c)
            # find smallest color < target_color not used
            for c in range(target_color):
                if not (used & (1 << c)):
                    new_coloring[u] = c
                    break
            else:
                # cannot directly reassign, try Kempe chains
                eliminated = False
                for c in range(target_color):
                    # Try to swap along (c, target_color) Kempe chain
                    # Find component containing u in subgraph of colors c and target_color
                    from collections import deque
                    visited = [False] * n
                    queue = deque([u])
                    visited[u] = True
                    component = []
                    has_c = False
                    has_target = False
                    while queue:
                        x = queue.popleft()
                        component.append(x)
                        col_x = new_coloring[x]
                        if col_x == c:
                            has_c = True
                        elif col_x == target_color:
                            has_target = True
                        for y in graph[x]:
                            if not visited[y]:
                                col_y = new_coloring[y]
                                if col_y == c or col_y == target_color:
                                    visited[y] = True
                                    queue.append(y)
                    # If component does not contain color c, we can swap
                    if not has_c:
                        # swap c and target_color in component
                        for x in component:
                            if new_coloring[x] == target_color:
                                new_coloring[x] = c
                            elif new_coloring[x] == c:
                                new_coloring[x] = target_color
                        new_coloring[u] = c  # now u is color c
                        eliminated = True
                        break
                    # else: swapping would not free color c for u (since c is present)
                if eliminated:
                    break
                else:
                    # Could not eliminate u via any Kempe chain
                    return None
        return new_coloring

    # Iteratively try to reduce colors
    current = best_coloring[:]
    changed = True
    while changed and count_colors(current) > 1:
        changed = False
        k = count_colors(current)
        # Try to eliminate color classes from highest to lowest
        for target_color in range(k-1, -1, -1):
            new_col = eliminate_color_class(current, target_color)
            if new_col is not None and is_valid(new_col):
                current = new_col
                changed = True
                break  # restart from highest color after elimination
        # Compact colors if any gaps (should not happen with our method, but safe)
        if changed:
            # remap colors to 0..k'-1
            unique_colors = {}
            next_color = 0
            for i in range(n):
                c = current[i]
                if c not in unique_colors:
                    unique_colors[c] = next_color
                    next_color += 1
                current[i] = unique_colors[c]

    # Final validation and compacting
    if not is_valid(current):
        # last resort: return best_coloring (should be valid)
        current = best_coloring
    # Ensure colors are consecutive
    mapping = {}
    next_c = 0
    for i in range(n):
        c = current[i]
        if c not in mapping:
            mapping[c] = next_c
            next_c += 1
        current[i] = mapping[c]

    return current

import math
import random
import time

def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    n = len(adj)
    if n == 0:
        return []
    if n == 1:
        return [0]

    # Determine if input is adjacency matrix or adjacency list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        # Check if it's a binary matrix
        is_matrix = True
        for i in range(n):
            for j in range(n):
                if adj[i][j] not in (0, 1):
                    is_matrix = False
                    break
            if not is_matrix:
                break

    # Build adjacency list and bitmask representation
    if is_matrix:
        adj_list = [[] for _ in range(n)]
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    adj_list[i].append(j)
    else:
        adj_list = adj

    # Build bitmask for fast operations
    bit_adj = [0] * n
    for u in range(n):
        for v in adj_list[u]:
            bit_adj[u] |= (1 << v)

    # Helper: greedy coloring with given vertex order
    def greedy_color(order):
        color = [-1] * n
        for v in order:
            # Compute neighbor colors mask
            neighbor_mask = 0
            for u in adj_list[v]:
                if color[u] != -1:
                    neighbor_mask |= (1 << color[u])
            # Find smallest available color (MEX)
            c = 0
            while neighbor_mask & (1 << c):
                c += 1
            color[v] = c
        return color

    # Helper: count number of colors used
    def count_colors(coloring):
        if not coloring:
            return 0
        return max(coloring) + 1

    # Helper: validate coloring
    def is_valid(coloring):
        for u in range(n):
            for v in adj_list[u]:
                if u < v and coloring[u] == coloring[v]:
                    return False
        return True

    # Helper: apply 1-opt local search (try to reduce color of each vertex)
    def local_search_1opt(coloring):
        improved = True
        # Work on a copy
        current = coloring[:]
        while improved:
            improved = False
            # Try to improve each vertex in random order
            order = list(range(n))
            random.shuffle(order)
            for v in order:
                # Try all colors from 0 up to current max color
                max_color = max(current) if current else 0
                for c in range(max_color + 1):
                    if c == current[v]:
                        continue
                    # Check if color c is valid for v
                    valid = True
                    for u in adj_list[v]:
                        if current[u] == c:
                            valid = False
                            break
                    if valid:
                        # Check if we can reduce the total number of colors
                        old_color = current[v]
                        current[v] = c
                        # Recolor higher colors if necessary to maintain compactness
                        # But first check validity
                        if is_valid(current):
                            # Compact colors: remap to 0..k-1
                            color_map = {}
                            next_color = 0
                            for i in range(n):
                                col = current[i]
                                if col not in color_map:
                                    color_map[col] = next_color
                                    next_color += 1
                                current[i] = color_map[col]
                            # If we reduced the number of colors, accept
                            if count_colors(current) < count_colors(coloring):
                                coloring[:] = current
                                improved = True
                                break
                        # Revert if not improving
                        current[v] = old_color
                if improved:
                    break
        return coloring

    # Generate multiple starting orders with randomization
    best_coloring = None
    best_num_colors = float('inf')

    # Order 1: Random order
    for _ in range(10):
        order = list(range(n))
        random.shuffle(order)
        coloring = greedy_color(order)
        if is_valid(coloring):
            num_colors = count_colors(coloring)
            if num_colors < best_num_colors:
                best_num_colors = num_colors
                best_coloring = coloring[:]

    # Order 2: Degree descending (Welsh-Powell)
    degree = [len(adj_list[i]) for i in range(n)]
    order = sorted(range(n), key=lambda x: (-degree[x], x))
    for _ in range(5):
        # Add small random perturbation
        perturbed = order[:]
        for i in range(n):
            if random.random() < 0.1:  # 10% chance to swap with a random neighbor
                j = random.randint(0, n-1)
                perturbed[i], perturbed[j] = perturbed[j], perturbed[i]
        coloring = greedy_color(perturbed)
        if is_valid(coloring):
            num_colors = count_colors(coloring)
            if num_colors < best_num_colors:
                best_num_colors = num_colors
                best_coloring = coloring[:]

    # Order 3: Random priority with degree bias
    for _ in range(10):
        priorities = [random.random() + 0.1 * degree[i] for i in range(n)]
        order = sorted(range(n), key=lambda x: (-priorities[x], x))
        coloring = greedy_color(order)
        if is_valid(coloring):
            num_colors = count_colors(coloring)
            if num_colors < best_num_colors:
                best_num_colors = num_colors
                best_coloring = coloring[:]

    # If no valid coloring found (shouldn't happen), use greedy on natural order
    if best_coloring is None:
        order = list(range(n))
        best_coloring = greedy_color(order)
        # Ensure validity (greedy should produce valid coloring)
        if not is_valid(best_coloring):
            # Fallback: assign each vertex a unique color
            best_coloring = list(range(n))

    # Apply local search to try to reduce colors
    start_time = time.time()
    best_coloring = local_search_1opt(best_coloring)
    # Ensure we don't exceed time limit by checking elapsed time
    # (but for n<=100, local search should be very fast)

    # Final validation and compactness
    if not is_valid(best_coloring):
        # Last resort: valid but not necessarily minimal coloring via DSATUR-like
        # Simple greedy with saturation heuristic
        color = [-1] * n
        # Track saturation: for each vertex, set of neighbor colors
        neighbor_colors = [set() for _ in range(n)]
        for _ in range(n):
            # Select uncolored vertex with max saturation degree
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if color[u] == -1:
                    sat = len(neighbor_colors[u])
                    deg = len(adj_list[u])
                    if sat > max_sat or (sat == max_sat and deg > max_deg):
                        max_sat = sat
                        max_deg = deg
                        v = u
            if v == -1:
                break  # Should not happen
            # Find smallest available color
            used = neighbor_colors[v]
            c = 0
            while c in used:
                c += 1
            color[v] = c
            # Update neighbor colors
            for u in adj_list[v]:
                if color[u] == -1:
                    neighbor_colors[u].add(c)
        best_coloring = color

    # Compact colors to 0..k-1
    color_map = {}
    next_color = 0
    for i in range(n):
        col = best_coloring[i]
        if col not in color_map:
            color_map[col] = next_color
            next_color += 1
        best_coloring[i] = color_map[col]

    return best_coloring

import math
import random

def color_graph(adj: list[list[int]]) -> list[int]:
    if not adj:
        return []
    n = len(adj)
    if n == 1:
        return [0]

    # Detect adjacency matrix vs list
    is_matrix = False
    if len(adj) > 0 and len(adj[0]) == len(adj):
        if all(all(x in (0, 1) for x in row) for row in adj):
            is_matrix = True

    # Build neighbor sets and bitmasks
    neighbors = [set() for _ in range(n)]
    bit_adj = [0] * n
    if is_matrix:
        for i in range(n):
            for j in range(n):
                if adj[i][j] == 1:
                    neighbors[i].add(j)
                    bit_adj[i] |= (1 << j)
    else:
        for i in range(n):
            for j in adj[i]:
                if 0 <= j < n:
                    neighbors[i].add(j)
                    bit_adj[i] |= (1 << j)

    # Helper: compute Jaccard similarity for non-adjacent pairs
    def jaccard_similarity(u, v):
        if v in neighbors[u]:
            return -1  # adjacent, skip
        inter = len(neighbors[u] & neighbors[v])
        union = len(neighbors[u] | neighbors[v])
        return inter / union if union != 0 else 0.0

    # Greedy coloring with Jaccard-based vertex ordering
    def greedy_color(order):
        color = [-1] * n
        for u in order:
            used = 0
            for v in neighbors[u]:
                c = color[v]
                if c != -1:
                    used |= (1 << c)
            c = 0
            while used & (1 << c):
                c += 1
            color[u] = c
        return color

    # Generate multiple orderings
    orders = []

    # 1. Degree descending
    orders.append(sorted(range(n), key=lambda x: len(neighbors[x]), reverse=True))

    # 2. Saturation degree (DSATUR-like)
    sat_order = []
    colored = [False] * n
    color_temp = [-1] * n
    sat = [0] * n
    for _ in range(n):
        # select uncolored vertex with max saturation, tie-break by degree
        candidates = [i for i in range(n) if not colored[i]]
        if not candidates:
            break
        max_sat = max(sat[i] for i in candidates)
        max_sat_vertices = [i for i in candidates if sat[i] == max_sat]
        if len(max_sat_vertices) > 1:
            max_deg = max(len(neighbors[i]) for i in max_sat_vertices)
            u = max((i for i in max_sat_vertices if len(neighbors[i]) == max_deg), key=lambda x: len(neighbors[x]))
        else:
            u = max_sat_vertices[0]
        sat_order.append(u)
        colored[u] = True
        # update saturation of uncolored neighbors
        for v in neighbors[u]:
            if not colored[v]:
                sat[v] += 1
    orders.append(sat_order)

    # 3. Jaccard-based ordering: prioritize vertices with high similarity to non-neighbors
    jaccard_order = []
    remaining = set(range(n))
    while remaining:
        best_u = None
        best_score = -1
        for u in remaining:
            # average Jaccard similarity with non-neighbors in remaining
            non_neighbors = [v for v in remaining if v != u and v not in neighbors[u]]
            if non_neighbors:
                avg_sim = sum(jaccard_similarity(u, v) for v in non_neighbors) / len(non_neighbors)
            else:
                avg_sim = 0
            # score: high avg similarity + high degree (to color constrained vertices early)
            score = avg_sim * len(neighbors[u])
            if score > best_score:
                best_score = score
                best_u = u
        jaccard_order.append(best_u)
        remaining.remove(best_u)
    orders.append(jaccard_order)

    # 4. Smallest-last ordering (degeneracy)
    deg = [len(neighbors[i]) for i in range(n)]
    order_sl = []
    remaining_sl = set(range(n))
    while remaining_sl:
        # find vertex of minimum degree in remaining subgraph
        min_deg = min(deg[v] for v in remaining_sl)
        min_vertices = [v for v in remaining_sl if deg[v] == min_deg]
        v = min_vertices[0]  # tie-break by index
        order_sl.append(v)
        remaining_sl.remove(v)
        for u in neighbors[v]:
            if u in remaining_sl:
                deg[u] -= 1
    orders.append(list(reversed(order_sl)))  # color in reverse peeling order

    # Evaluate all orderings and keep the best (fewest colors)
    best_coloring = None
    best_num_colors = float('inf')
    for order in orders:
        col = greedy_color(order)
        num_colors = max(col) + 1 if col else 0
        if num_colors < best_num_colors:
            best_num_colors = num_colors
            best_coloring = col

    # Optional: try to reduce colors via Kempe chain swaps (limited to avoid timeout)
    def is_valid(coloring):
        for u in range(n):
            for v in neighbors[u]:
                if coloring[u] == coloring[v]:
                    return False
        return True

    def kempe_reduce(coloring, max_attempts=1000):
        k = max(coloring) + 1
        if k <= 1:
            return coloring
        # Try to eliminate the last color (k-1)
        for _ in range(max_attempts):
            color_class = [v for v in range(n) if coloring[v] == k-1]
            if not color_class:
                break  # color already eliminated
            made_progress = False
            for v in color_class:
                # Try direct reassignment to a lower color
                for c in range(k-1):
                    if all(coloring[u] != c for u in neighbors[v]):
                        coloring[v] = c
                        made_progress = True
                        break
                if made_progress:
                    break
                # Try Kempe chain swap with each lower color
                for c in range(k-1):
                    # Find the (v, c)-Kempe chain containing v
                    stack = [v]
                    visited = set()
                    component = set()
                    while stack:
                        node = stack.pop()
                        if node in visited:
                            continue
                        visited.add(node)
                        if coloring[node] == k-1 or coloring[node] == c:
                            component.add(node)
                            for nb in neighbors[node]:
                                if nb not in visited and (coloring[nb] == k-1 or coloring[nb] == c):
                                    stack.append(nb)
                    # Check if swapping this component would free color c for v
                    # After swap, v would get color c, so we need that no neighbor of v has color c (after swap)
                    # Neighbors of v that are in the component will flip from c to k-1 or vice versa
                    # We need that for all neighbors u of v:
                    #   if u in component: after swap, color[u] = k-1 if was c, or c if was k-1
                    #   else: color[u] unchanged
                    # So we need that no neighbor u of v has color c after swap.
                    # That is: for all neighbors u of v:
                    #   if u in component: then original color[u] != c (because if it was c, after swap it becomes k-1)
                    #   else: original color[u] != c
                    # But note: if u in component and original color[u] == c, after swap it becomes k-1 -> safe
                    # Actually, we need that after swap, no neighbor has color c.
                    # Let's compute the color of neighbors after swap:
                    #   For neighbor u:
                    #     if u in component:
                    #         if coloring[u] == c -> becomes k-1
                    #         if coloring[u] == k-1 -> becomes c
                    #     else: unchanged
                    # So neighbor u has color c after swap iff:
                    #   (u in component and coloring[u] == k-1) or (u not in component and coloring[u] == c)
                    conflict = False
                    for u in neighbors[v]:
                        if (u in component and coloring[u] == k-1) or (u not in component and coloring[u] == c):
                            conflict = True
                            break
                    if not conflict:
                        # perform the swap
                        for node in component:
                            if coloring[node] == c:
                                coloring[node] = k-1
                            elif coloring[node] == k-1:
                                coloring[node] = c
                        made_progress = True
                        break
                if made_progress:
                    break
            if not made_progress:
                break
        # compact colors if possible
        used = set(coloring)
        if len(used) < k:
            mapping = {old: new for new, old in enumerate(sorted(used))]
            coloring = [mapping[c] for c in coloring]
        return coloring

    # Apply Kempe reduction a few times
    for _ in range(3):
        new_coloring = kempe_reduce(best_coloring.copy(), max_attempts=200)
        if is_valid(new_coloring):
            new_num_colors = max(new_coloring) + 1 if new_coloring else 0
            if new_num_colors < best_num_colors:
                best_coloring = new_coloring
                best_num_colors = new_num_colors
        else:
            break

    return best_coloring

