    # Candidate 1: Welsh-Powell with degree tie-breaking (stable sort)
    order_wp = sorted(range(n), key=lambda x: (-degree[x], x))
    color_wp = greedy_color(order_wp)
    best_coloring = color_wp[:]
    best_k = count_colors(best_coloring)

    # Candidate 2: DSATUR with degree tie-breaking and random tie-break
    def dsatur():
        color = [-1] * n
        # saturation: number of distinct colors in neighborhood
        saturation = [0] * n
        # colored neighbor masks for fast saturation update
        colored_mask = [0] * n
