        for _ in range(n):
            # Select uncolored vertex with max saturation, tie-break by degree, then random
            candidates = []
            max_sat = -1
            for v in uncolored:
                sat_v = saturation[v]
                if sat_v > max_sat:
                    max_sat = sat_v
                    candidates = [v]
                elif sat_v == max_sat:
                    candidates.append(v)
