            max_deg = -1
            best_vs = []
            for v in candidates:
                # degree in uncolored subgraph: neighbors that are uncolored
                deg_in_uncolored = 0
                for w in neighbors[v]:
                    if w in uncolored:
                        deg_in_uncolored += 1
                if deg_in_uncolored > max_deg:
                    max_deg = deg_in_uncolored
                    best_vs = [v]
                elif deg_in_uncolored == max_deg:
                    best_vs.append(v)
            v = random.choice(best_vs) if len(best_vs) > 1 else best_vs[0]

            # Assign smallest available color
            used = colored_mask[v]
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c

            # Update uncolored and saturation info
            uncolored.remove(v)
            for w in neighbors[v]:
                if w in uncolored:
                    # Add color c to w's saturation if not already present
                    if not (colored_mask[w] & (1 << c)):
                        colored_mask[w] |= (1 << c)
                        saturation[w] += 1
        return color

    # Run DSATUR multiple times with different random seeds for tie-breaking
    for seed in range(5):
        random.seed(seed)
        color_ds = dsatur()
        if is_valid(color_ds):
            k_ds = count_colors(color_ds)
            if k_ds < best_k:
                best_k = k_ds
                best_coloring = color_ds[:]

    # Candidate 3: RLF (Recursive Largest First)
    def rlf():
        color = [-1] * n
        uncolored = set(range(n))
        c = 0
        while uncolored:
            # Build maximal independent set for color c
            # Start with vertex of max degree in uncolored subgraph
            max_deg = -1
            v0 = -1
            for v in uncolored:
                deg = 0
                for w in neighbors[v]:
                    if w in uncolored:
                        deg += 1
                if deg > max_deg:
                    max_deg = deg
                    v0 = v
            S = {v0}
            # U: vertices not adjacent to S (eligible)
            # W: vertices adjacent to S (ineligible)
            U = set(uncolored - {v0}) - neighbors[v0]
            W = set(uncolored) - U - S
            while U:
                # Select u in U with max |N(u) ∩ W|
                max_score = -1
                best_u = -1
                for u in U:
                    score = 0
                    for w in neighbors[u]:
                        if w in W:
                            score += 1
                    if score > max_score:
                        max_score = score
                        best_u = u
                    elif score == max_score:
                        # Tie-break: min degree in G[U]
                        deg_u = 0
                        for w in neighbors[u]:
                            if w in U:
                                deg_u += 1
                        deg_best = 0
                        for w in neighbors[best_u]:
                            if w in U:
                                deg_best += 1
                        if deg_u < deg_best:
                            best_u = u
                u = best_u
                S.add(u)
                U.remove(u)
                # Move neighbors of u from U to W
                for w in neighbors[u]:
                    if w in U:
                        U.remove(w)
                        W.add(w)
            # Assign color c to all in S
            for v in S:
                color[v] = c
            uncolored -= S
            c += 1
