    color_rlf = rlf()
    if is_valid(color_rlf):
        k_rlf = count_colors(color_rlf)
        if k_rlf < best_k:
            best_k = k_rlf
            best_coloring = color_rlf[:]

    # Candidate 4: Smallest-Last ordering (Matula & Beck)
    def smallest_last():
        # Compute core decomposition ordering (smallest-last)
        # We'll compute the degeneracy ordering by repeatedly removing min degree vertex
        remaining = set(range(n))
        degree_current = degree[:]  # copy
        order = []
        # Bucket sort for efficiency
        max_deg = max(degree) if n > 0 else 0
        buckets = [set() for _ in range(max_deg + 1)]
        for v in range(n):
            d = degree_current[v]
            if d <= max_deg:
                buckets[d].add(v)
        # Pointer to current non-empty bucket
        ptr = 0
        for _ in range(n):
            # Find non-empty bucket
            while ptr <= max_deg and not buckets[ptr]:
                ptr += 1
            if ptr > max_deg:
                break  # should not happen
            v = buckets[ptr].pop()
            order.append(v)
            # Update neighbors
            for w in neighbors[v]:
                if w in remaining:
                    d_old = degree_current[w]
                    buckets[d_old].remove(w)
                    degree_current[w] -= 1
                    d_new = degree_current[w]
                    if d_new <= max_deg:
                        buckets[d_new].add(w)
                    # Update ptr if needed
                    if d_new < ptr:
                        ptr = d_new
            remaining.remove(v)
        # Color in reverse order
        return greedy_color(list(reversed(order)))

    color_sl = smallest_last()
    if is_valid(color_sl):
        k_sl = count_colors(color_sl)
        if k_sl < best_k:
            best_k = k_sl
            best_coloring = color_sl[:]

    # Ensure coloring is valid and compact
    def compact_colors(coloring):
        # Map colors to 0..k-1
        unique_colors = {}
        next_color = 0
        for i in range(n):
            c = coloring[i]
            if c not in unique_colors:
                unique_colors[c] = next_color
                next_color += 1
            coloring[i] = unique_colors[c]
        return coloring

    best_coloring = compact_colors(best_coloring)
    # Final validation (should always hold)
    if not is_valid(best_coloring):
        # Fallback to Welsh-Powell (should be valid)
        best_coloring = greedy_color(sorted(range(n), key=lambda x: (-degree[x], x)))
        best_coloring = compact_colors(best_coloring)
    return best_coloring

