            # Select vertex with max saturation, tie-break by degree in uncolored subgraph
            v = max(uncolored, key=lambda x: (sat[x], len([y for y in neighbors[x] if y in uncolored])))
            # Find smallest available color
            used = 0
            for y in neighbors[v]:
                if color[y] != -1:
                    used |= (1 << color[y])
            c = 0
            while used & (1 << c):
                c += 1
            color[v] = c
            uncolored.remove(v)
