            independent_set = {v}
            # U: vertices not adjacent to any in independent_set
            U = {y for y in uncolored if y != v and not any(z in independent_set for z in neighbors[y])}
            W = uncolored - independent_set - U
            while U:
                # Select u in U with max |N(u) ∩ W|
                u = max(U, key=lambda x: len([y for y in neighbors[x] if y in W]))
                independent_set.add(u)
                U.remove(u)
                # Move neighbors of u in U to W
                for y in list(U):
                    if y in neighbors[u]:
                        U.remove(y)
                        W.add(y)
            for u in independent_set:
                color[u] = c
                uncolored.remove(u)
            c += 1
        return color

    # Smallest-Last ordering
    def smallest_last():
        order = []
        remaining = set(range(n))
        deg = [len(neighbors[i]) for i in range(n)]
        while remaining:
            # Find vertex with min degree in remaining subgraph
            v = min(remaining, key=lambda x: sum(1 for y in neighbors[x] if y in remaining))
            order.append(v)
            remaining.remove(v)
            # Update degrees (not strictly needed for correctness but for efficiency)
