    if best_coloring is None:
        best_coloring = greedy_color(list(range(n)))
        best_k = count_colors(best_coloring)

    # Kempe chain-based color reduction
    def kempe_reduce(coloring, k_target):
        # Try to eliminate color k_target-1
        color_class = [i for i in range(n) if coloring[i] == k_target-1]
        if not color_class:
            return coloring, k_target-1

        # Try direct reassignment
        for v in color_class:
            used = 0
            for u in neighbors[v]:
                if coloring[u] != -1 and coloring[u] < k_target-1:
                    used |= (1 << coloring[u])
            for c in range(k_target-1):
                if not (used & (1 << c)):
                    coloring[v] = c
                    color_class.remove(v)
                    break

        if not color_class:
            # Successfully eliminated, compact colors
            new_coloring = [-1] * n
            color_map = {}
            next_color = 0
            for i in range(n):
                if coloring[i] == k_target-1:
                    continue  # should be none
                if coloring[i] not in color_map:
                    color_map[coloring[i]] = next_color
                    next_color += 1
                new_coloring[i] = color_map[coloring[i]]
            return new_coloring, next_color

        # Try Kempe chains for each vertex in color class
        for v in color_class[:]:
            for c in range(k_target-1):
                # Build (c, k_target-1)-Kempe chain containing v
                if coloring[v] != k_target-1:
                    continue
                stack = [v]
                visited = set()
                component = set()
                while stack:
                    node = stack.pop()
                    if node in visited:
                        continue
                    visited.add(node)
                    if coloring[node] == c or coloring[node] == k_target-1:
                        component.add(node)
                        for nb in neighbors[node]:
                            if nb not in visited and (coloring[nb] == c or coloring[nb] == k_target-1):
                                stack.append(nb)
                # Check if we can swap: no neighbor of v in component has color c (would cause conflict)
                conflict = False
                for node in component:
                    for nb in neighbors[node]:
                        if nb not in component and coloring[nb] == c:
                            conflict = True
                            break
                    if conflict:
                        break
                if not conflict:
                    # Perform swap
                    for node in component:
                        if coloring[node] == c:
                            coloring[node] = k_target-1
                        else:
                            coloring[node] = c
                    # v should now be color c
                    if coloring[v] == c:
                        color_class.remove(v)
                        break  # break color loop, continue with next v
            if not color_class:
                break

        if not color_class:
            new_coloring = [-1] * n
            color_map = {}
            next_color = 0
            for i in range(n):
                if coloring[i] == k_target-1:
                    continue
                if coloring[i] not in color_map:
                    color_map[coloring[i]] = next_color
                    next_color += 1
                new_coloring[i] = color_map[coloring[i]]
            return new_coloring, next_color

        return coloring, k_target  # could not reduce

    # Iterative reduction with Tabu Search fallback
    current_coloring = best_coloring[:]
    current_k = best_k
    max_reduction_attempts = 10
    for _ in range(max_reduction_attempts):
        if current_k <= 1:
            break
        new_coloring, new_k = kempe_reduce(current_coloring[:], current_k)
        if new_k < current_k:
            current_coloring = new_coloring
            current_k = new_k
        else:
            # Apply limited Tabu Search to try to enable reduction
            # Fix target colors to current_k-1, try to resolve conflicts by moving vertices
            tabu_tenure = 5
            tabu = {}  # (vertex, color) -> time until which tabu
            iteration = 0
            max_tabu_steps = 30
            while iteration < max_tabu_steps and current_k > 1:
                # Find conflicting vertices (those with color current_k-1 that have neighbors of same color)
                conflicts = []
                for v in range(n):
                    if current_coloring[v] == current_k-1:
                        for u in neighbors[v]:
                            if current_coloring[u] == current_k-1:
                                conflicts.append(v)
                                break
                if not conflicts:
                    break  # color class is independent, can try to eliminate
                v = random.choice(conflicts) if conflicts else random.choice(range(n))
                # Try to move v to a different color
                best_move = None
                best_score = float('inf')
                for c in range(current_k):  # try all colors including current
                    if tabu.get((v, c), 0) > iteration:
