                    # Compute conflicts if we move v to c
                    same_color = 0
                    for u in neighbors[v]:
                        if current_coloring[u] == c:
                            same_color += 1
                    # Score: number of conflicts after move (lower is better)
                    score = same_color
                    if score < best_score:
                        best_score = score
                        best_move = (v, c)
                if best_move is None:
                    break
                v, c = best_move
                # Apply move
                old_color = current_coloring[v]
                current_coloring[v] = c
                # Update tabu
                tabu[(v, old_color)] = iteration + tabu_tenure
                iteration += 1
            # After Tabu, try Kempe reduction again
            new_coloring, new_k = kempe_reduce(current_coloring[:], current_k)
