    # Compact colors
    color_map = {}
    next_color = 0
    for i in range(n):
        if current_coloring[i] not in color_map:
            color_map[current_coloring[i]] = next_color
            next_color += 1
        current_coloring[i] = color_map[current_coloring[i]]

    return current_coloring

