def color_graph(adj: list[list[int]]) -> list[int]:
    # Handle empty graph
    if not adj:
        return []
    n = len(adj)
    if n == 0:
        return []

    # Detect if input is adjacency matrix (square and binary)
    is_matrix = False
    if n > 0 and len(adj[0]) == n:
        is_matrix = True
        for i in range(n):
            if len(adj[i]) != n:
                is_matrix = False
                break
            if is_matrix:
                for val in adj[i]:
                    if val not in (0, 1):
                        is_matrix = False
                        break
            if not is_matrix:
                break

    # Build adjacency list and degree array
    if is_matrix:
        adj_list = []
        for i in range(n):
            neighbors = []
            row = adj[i]
            for j in range(n):
                if row[j] == 1:
                    neighbors.append(j)
            adj_list.append(neighbors)
    else:
        adj_list = adj

    # Compute degrees
    degree = [len(adj_list[i]) for i in range(n)]

    # Handle trivial cases
    if n == 1:
        return [0]
    if all(d == 0 for d in degree):
        return [0] * n

    # Order vertices by degree descending
    order = sorted(range(n), key=lambda x: (-degree[x], x))

    # Initialize color array and neighbor color tracking
    color = [-1] * n
    neighbor_colors = [set() for _ in range(n)]

    # Process vertices in order
    for v in order:
        # Find the smallest available color not used by colored neighbors
        used = neighbor_colors[v]
        c = 0
        while c in used:
            c += 1
        color[v] = c

        # Update neighbor color sets for uncolored neighbors
        for u in adj_list[v]:
            if color[u] == -1:
                neighbor_colors[u].add(c)

    # Compact colors to 0..k-1
    unique_colors = sorted(set(color))
    mapping = {old: new for new, old in enumerate(unique_colors)}
    compacted = [mapping[c] for c in color]

    return compacted

