        visited = [False] * n
        order = []
        buckets = [[] for _ in range(n)]
        for i in range(n):
            if degrees[i] < n:
                buckets[degrees[i]].append(i)
        pos = 0
        for d in range(n):
            while buckets[d]:
                v = buckets[d].pop()
                if visited[v]:
                    continue
                visited[v] = True
                order.append(v)
                for u in graph[v]:
                    if not visited[u]:
                        degrees[u] -= 1
                        if degrees[u] < n:
                            buckets[degrees[u]].append(u)
        return order[::-1]  # reverse for coloring order

    # Helper: DSATUR with degree tie-breaking
    def dsatur():
        if n == 0:
            return []
        coloring = [-1] * n
        saturated = [set() for _ in range(n)]
        # degree in the full graph for tie-breaking
        degrees = [len(graph[i]) for i in range(n)]
        for _ in range(n):
            # select uncolored vertex with max saturation, tie-break by degree
            v = -1
            max_sat = -1
            max_deg = -1
            for u in range(n):
                if coloring[u] == -1:
                    sat = len(saturated[u])
                    if sat > max_sat or (sat == max_sat and degrees[u] > max_deg):
                        max_sat = sat
                        max_deg = degrees[u]
