    except:
        pass

    # 4. RLF
    try:
        c4 = rlf()
        if is_valid(c4):
            candidates.append(c4)
    except:
        pass

    # If no candidate (should not happen), fallback to trivial
    if not candidates:
        candidates.append([0] * n)

    # Select best candidate (fewest colors)
    best = min(candidates, key=num_colors)
    k = num_colors(best)

    # Iterative Kempe chain color reduction
    improved = True
