    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_times = times[job]
            t[0] += job_times[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + job_times[m]
        return t[-1]

    def forward_pass(seq):
        k = len(seq)
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job_times = times[seq[r]]
            if r == 0:
                e[0][0] = job_times[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job_times[m]
            else:
                e[r][0] = e[r-1][0] + job_times[0]
                for m in range(1, M):
                    e[r][m] = max(e[r-1][m], e[r][m-1]) + job_times[m]
        return e

    def backward_pass(seq):
        k = len(seq)
        q = [[0] * M for _ in range(k+1)]
