            f[0] = job_t[0]
            for m in range(1, M):
                f[m] = max(f[m-1], 0) + job_t[m]
        else:
            f[0] = e[0] + job_t[0]
            for m in range(1, M):
                f[m] = max(f[m-1], e[m]) + job_t[m]
        q = [0] * M
        for idx in range(k-1, pos-1, -1):
            job_t = times[seq[idx]]
            q[M-1] += job_t[M-1]
            for m in range(M-2, -1, -1):
                q[m] = max(q[m], q[m+1]) + job_t[m]
        max_val = 0
        for m in range(M):
            val = f[m] + q[m]
            if val > max_val:
                max_val = val
        return max_val

    best_seq = [order[0], order[1]] if makespan([order[0], order[1]]) <= makespan([order[1], order[0]]) else [order[1], order[0]]
    for k in range(2, N):
        job = order[k]
        best_pos = 0
        best_cost = taillard_insertion_cost(best_seq, job, 0)
        for pos in range(1, k+1):
            cost = taillard_insertion_cost(best_seq, job, pos)
            if cost < best_cost:
                best_cost = cost
                best_pos = pos
        best_seq.insert(best_pos, job)

    current_seq = best_seq[:]
    best_seq_ever = current_seq[:]
    best_makespan_ever = taillard_makespan(best_seq_ever)
    LB = 0
    for m in range(M):
        min_pre = min(sum(times[i][:m]) for i in range(N)) if m > 0 else 0
        min_suf = min(sum(times[i][m+1:]) for i in range(N)) if m < M-1 else 0
        machine_sum = sum(times[i][m] for i in range(N))
        LB = max(LB, min_pre + machine_sum + min_suf)
    if best_makespan_ever == LB:
        return best_seq_ever

    T_param = 0.5
    avg_p = sum(total_processing) / (N * M)
    T = T_param * avg_p / (10 * N * M) * N * M
    T = max(T, 1e-6)
    d = 3 if N > 20 else 2
    max_iter = 60
    for _ in range(max_iter):
        if len(current_seq) <= d:
            destroyed = []
            R = current_seq[:]
            random.shuffle(R)
        else:
            indices = random.sample(range(len(current_seq)), d)
            indices.sort(reverse=True)
            R = [current_seq.pop(i) for i in indices]
            destroyed = current_seq
        random.shuffle(R)
        for job in R:
            best_pos = 0
            best_cost = taillard_insertion_cost(destroyed, job, 0)
            for pos in range(1, len(destroyed)+1):
                cost = taillard_insertion_cost(destroyed, job, pos)
                if cost < best_cost:
                    best_cost = cost
                    best_pos = pos
            destroyed.insert(best_pos, job)
        current_seq = destroyed
        current_makespan = taillard_makespan(current_seq)
        if current_makespan < best_makespan_ever:
            best_makespan_ever = current_makespan
            best_seq_ever = current_seq[:]
        if current_makespan < taillard_makespan(best_seq):
            best_seq = current_seq[:]
        elif random.random() < math.exp(-(current_makespan - taillard_makespan(best_seq)) / T):
            best_seq = current_seq[:]
    return best_seq_ever

