import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute total processing times for NEH ordering
    total_times = [sum(job) for job in times]
    order = sorted(range(N), key=lambda i: total_times[i], reverse=True)

    # Preallocate matrices for Taillard acceleration
    e = [[0] * M for _ in range(N)]
    q = [[0] * M for _ in range(N)]
    f = [0] * M

    def makespan_from_perm(perm):
        if not perm:
            return 0
        # Initialize first job
        e[0][0] = times[perm[0]][0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + times[perm[0]][m]
        # Forward pass for remaining jobs
        for i in range(1, len(perm)):
            job_idx = perm[i]
            e[i][0] = e[i-1][0] + times[job_idx][0]
            for m in range(1, M):
                e[i][m] = max(e[i-1][m], e[i][m-1]) + times[job_idx][m]
        return e[len(perm)-1][M-1]

    def makespan_with_insertion(perm, pos, job_idx):
        k = len(perm)
        # Compute forward vector f for insertion at position pos
        if pos == 0:
            f[0] = times[job_idx][0]
            for m in range(1, M):
                f[m] = f[m-1] + times[job_idx][m]
        else:
            f[0] = e[pos-1][0] + times[job_idx][0]
            for m in range(1, M):
                f[m] = max(f[m-1], e[pos-1][m]) + times[job_idx][m]
        # Compute makespan using forward vector f and backward tail q
        makespan = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > makespan:
                makespan = val
        return makespan

    def neh_construct(start_idx=0):
        # Reset e and q for new construction
        for i in range(N):
            for m in range(M):
                e[i][m] = 0
                q[i][m] = 0
        perm = []
        # Build permutation incrementally
        for idx in range(start_idx, N):
            job_idx = order[idx]
            k = len(perm)
            if k == 0:
                perm.append(job_idx)
                # Update e for first job
                e[0][0] = times[job_idx][0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + times[job_idx][m]
                # Update q for first job (only one job)
                for m in range(M):
                    q[0][m] = times[job_idx][m]
                continue
            # Evaluate all k+1 insertion positions
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(k+1):
                # Compute forward vector f for job_idx at position pos
                if pos == 0:
                    f[0] = times[job_idx][0]
                    for m in range(1, M):
                        f[m] = f[m-1] + times[job_idx][m]
                else:
                    f[0] = e[pos-1][0] + times[job_idx][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[pos-1][m]) + times[job_idx][m]
                # Compute makespan for this insertion
                ms = 0
                for m in range(M):
                    val = f[m] + q[pos][m]
                    if val > ms:
                        ms = val
                if ms < best_makespan:
                    best_makespan = ms
                    best_pos = pos
            # Insert job at best_pos
            perm.insert(best_pos, job_idx)
            # Recompute e and q for the new permutation of length k+1
            new_len = k+1
            # Forward pass
            for i in range(new_len):
                job_i = perm[i]
                if i == 0:
                    e[0][0] = times[job_i][0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + times[job_i][m]
                else:
                    e[i][0] = e[i-1][0] + times[job_i][0]
                    for m in range(1, M):
                        e[i][m] = max(e[i-1][m], e[i][m-1]) + times[job_i][m]
            # Backward pass
            for m in range(M):
                q[new_len][m] = 0
            for i in range(new_len-1, -1, -1):
                job_i = perm[i]
                if i == new_len-1:
                    q[i][M-1] = times[job_i][M-1]
                    for m in range(M-2, -1, -1):
                        q[i][m] = max(q[i+1][m], q[i][m+1]) + times[job_i][m]
                else:
                    q[i][M-1] = q[i+1][M-1] + times[job_i][M-1]
                    for m in range(M-2, -1, -1):
                        q[i][m] = max(q[i+1][m], q[i][m+1]) + times[job_i][m]
        return perm

    # Compute lower bound for early termination (Taillard's LB)
    LB = 0
    for m in range(M):
        min_before = min(times[i][:m] for i in range(N)) if m > 0 else [0]*N
        min_after = min(times[i][m+1:] for i in range(N)) if m < M-1 else [0]*N
        sum_m = sum(times[i][m] for i in range(N))
        lb_m = min(sum(row[:m]) for row in times) + sum_m + min(sum(row[m+1:]) for row in times) if m > 0 and m < M-1 else \
               (sum_m + min(sum(row[m+1:]) for row in times)) if m == 0 else \
               (min(sum(row[:m]) for row in times) + sum_m) if m == M-1 else 0
        if lb_m > LB:
            LB = lb_m

    # Initial solution via NEH
    current_perm = neh_construct(0)
    best_perm = current_perm[:]
    best_makespan = makespan_from_perm(best_perm)
    if best_makespan == LB:
        return best_perm

    # Iterated Greedy parameters
    T_param = 0.5
    total_processing = sum(total_times)
    T = T_param * total_processing / (10 * N * M)
    d = 3 if N > 20 else 2
    max_iter = 60
    iter_count = 0

    while iter_count < max_iter:
        # Destruction: remove d random jobs
        indices = list(range(N))
        random.shuffle(indices)
        removed_indices = indices[:d]
        removed_jobs = [current_perm[i] for i in removed_indices]
        # Build destroyed permutation
        destroyed_perm = [current_perm[i] for i in indices[d:]]

        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed_jobs)
        for job_idx in removed_jobs:
            k = len(destroyed_perm)
            if k == 0:
                destroyed_perm.append(job_idx)
                # Update e and q for single job
                e[0][0] = times[job_idx][0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + times[job_idx][m]
                for m in range(M):
                    q[0][m] = times[job_idx][m]
                continue
            best_pos = 0
            best_makespan = float('inf')
            for pos in range(k+1):
                # Compute forward vector f for job_idx at position pos
                if pos == 0:
                    f[0] = times[job_idx][0]
                    for m in range(1, M):
                        f[m] = f[m-1] + times[job_idx][m]
                else:
                    f[0] = e[pos-1][0] + times[job_idx][0]
                    for m in range(1, M):
                        f[m] = max(f[m-1], e[pos-1][m]) + times[job_idx][m]
                # Compute makespan for this insertion
                ms = 0
                for m in range(M):
                    val = f[m] + q[pos][m]
                    if val > ms:
                        ms = val
                if ms < best_makespan:
                    best_makespan = ms
                    best_pos = pos
            # Insert job at best_pos
            destroyed_perm.insert(best_pos, job_idx)
            # Recompute e and q for the new permutation
            new_len = k+1
            # Forward pass
            for i in range(new_len):
                job_i = destroyed_perm[i]
                if i == 0:
                    e[0][0] = times[job_i][0]
                    for m in range(1, M):
                        e[0][m] = e[0][m-1] + times[job_i][m]
                else:
                    e[i][0] = e[i-1][0] + times[job_i][0]
                    for m in range(1, M):
                        e[i][m] = max(e[i-1][m], e[i][m-1]) + times[job_i][m]
            # Backward pass
            for m in range(M):
                q[new_len][m] = 0
            for i in range(new_len-1, -1, -1):
                job_i = destroyed_perm[i]
                if i == new_len-1:
                    q[i][M-1] = times[job_i][M-1]
                    for m in range(M-2, -1, -1):
                        q[i][m] = max(q[i+1][m], q[i][m+1]) + times[job_i][m]
                else:
                    q[i][M-1] = q[i+1][M-1] + times[job_i][M-1]
                    for m in range(M-2, -1, -1):
                        q[i][m] = max(q[i+1][m], q[i][m+1]) + times[job_i][m]

        # Compute makespan of new solution
        new_makespan = makespan_from_perm(destroyed_perm)

        # Acceptance criterion
        if new_makespan < makespan_from_perm(current_perm):
            current_perm = destroyed_perm[:]
            if new_makespan < best_makespan:
                best_perm = destroyed_perm[:]
                best_makespan = new_makespan
                if best_makespan == LB:
                    break
        else:
            delta = new_makespan - makespan_from_perm(current_perm)
            if random.random() < math.exp(-delta / T):
                current_perm = destroyed_perm[:]

        iter_count += 1

    return best_perm

