def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1.0

    P = [sum(job) for job in times]
    order = sorted(range(N), key=lambda i: P[i], reverse=True)

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + job_t[m]
        return t[-1]

    def taillard_makespan(partial, job):
        k = len(partial)
        if k == 0:
            f = [0] * M
            job_t = times[job]
            f[0] = job_t[0]
            for m in range(1, M):
                f[m] = f[m-1] + job_t[m]
            return f[-1]
        e = [[0] * M for _ in range(k)]
        job_t0 = times[partial[0]]
        e[0][0] = job_t0[0]
        for m in range(1, M):
            e[0][m] = e[0][m-1] + job_t0[m]
        for r in range(1, k):
            job_rt = times[partial[r]]
            e[r][0] = e[r-1][0] + job_rt[0]
            for m in range(1, M):
                e[r][m] = max(e[r-1][m], e[r][m-1]) + job_rt[m]
        q = [[0] * M for _ in range(k+1)]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job_rt = times[partial[r]]
            q[r][M-1] = q[r+1][M-1] + job_rt[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_rt[m]
        best_cmax = float('inf')
        best_pos = 0
        job_t = times[job]
        for i in range(k+1):
            if i == 0:
                f0 = job_t[0]
                f = [0] * M
                f[0] = f0
                for m in range(1, M):
                    f[m] = f[m-1] + job_t[m]
            else:
                prev_e = e[i-1]
                f = [0] * M
                f[0] = prev_e[0] + job_t[0]
                for m in range(1, M):
                    f[m] = max(f[m-1], prev_e[m]) + job_t[m]
            cmax = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > cmax:
                    cmax = val
            if cmax < best_cmax:
                best_cmax = cmax
                best_pos = i
        return best_cmax, best_pos

    current = [order[0]]
    for idx in range(1, N):
        job = order[idx]
        _, pos = taillard_makespan(current, job)
        current.insert(pos, job)
    best = current[:]
    best_cmax = makespan(best)

    LB = 0
    for m in range(M):
        min_before = min((sum(times[i][:m]) for i in range(N)), default=0)
        machine_sum = sum(times[i][m] for i in range(N))
        min_after = min((sum(times[i][m+1:]) for i in range(N)), default=0)
        LB = max(LB, min_before + machine_sum + min_after)
    if best_cmax == LB:
        return best

    max_iter = 60
    d = 3
    for _ in range(max_iter):
        if len(current) < d:
            break
        indices = random.sample(range(len(current)), d)
        indices.sort(reverse=True)
        removed = [current.pop(i) for i in indices]
        random.shuffle(removed)
        for job in removed:
            _, pos = taillard_makespan(current, job)
            current.insert(pos, job)
        curr_cmax = makespan(current)
        if curr_cmax < best_cmax:
            best_cmax = curr_cmax
            best = current[:]
        if curr_cmax < makespan(best):
            pass
        if curr_cmax < makespan(current):
            pass
        if curr_cmax < makespan(best):
            best = current[:]
            best_cmax = curr_cmax
        if curr_cmax < makespan(current):
            pass
        delta = curr_cmax - makespan(current)
        if delta < 0 or random.random() < math.exp(-delta / T):
            pass
        else:
            for job in removed:
                current.insert(random.randint(0, len(current)), job)
        if best_cmax == LB:
            break

    return best

