            for m in range(1, M):
                f[m] = f[m-1] + job_times[m]
        else:
            f[0] = e_prev[pos-1][0] + job_times[0]
            for m in range(1, M):
                f[m] = max(f[m-1], e_prev[pos-1][m]) + job_times[m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q_next[pos][m]
            if val > makespan_val:
