        seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        for idx in range(2, N):
            job = order[idx]
            e = forward_pass(seq)
            q = backward_pass(seq)
            best_pos = 0
            best_cost = insertion_cost(seq, job, 0, e, q)
            for pos in range(1, len(seq)+1):
                cost = insertion_cost(seq, job, pos, e, q)
