        current_makespan = makespan(current_seq)

        if current_makespan < best_makespan:
            best_makespan = current_makespan
            best_seq = current_seq[:]

        if current_makespan < makespan(seq):
            seq = current_seq
        else:
            delta = current_makespan - makespan(seq)
