                            f[m] = max(f[m-1], 0) + job_times[job][m]
                    else:
                        prev_pt = job_times[destroyed[i-1]]
                        f[0] = e[i-1][0] + job_times[job][0]
                        for m in range(1, M):
                            f[m] = max(f[m-1], e[i-1][m]) + job_times[job][m]
                    mk = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > mk:
                            mk = val
                    if mk < best_mk_local:
                        best_mk_local = mk
                        best_pos = i
                destroyed.insert(best_pos, job)
            new_seq = destroyed
            new_mk = makespan(new_seq)
            # Acceptance criterion
            if new_mk < current_mk or random.random() < math.exp(-(new_mk - current_mk) / T):
                current = new_seq
                current_mk = new_mk
                if new_mk < best_mk:
                    best = new_seq[:]
                    best_mk = new_mk
                    if best_mk == lb:  # Early exit if lower bound reached
                        break
        return best, best_mk

    # Compute Taillard's lower bound for early termination
    lb = 0
    for m in range(M):
        min_pre = min(sum(job_times[i][:m]) for i in range(N)) if m > 0 else 0
        min_suf = min(sum(job_times[i][m+1:]) for i in range(N)) if m < M-1 else 0
        machine_load = sum(job_times[i][m] for i in range(N))
        lb_m = min_pre + machine_load + min_suf
        if lb_m > lb:
            lb = lb_m

    # Construct initial solution
    init_seq = construct_initial()
    init_mk = makespan(init_seq)
    if init_mk == lb:
        return init_seq

    # Apply Iterated Greedy
    best_seq, _ = iterated_greedy(init_seq, init_mk)
    return best_seq

