def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Precompute job data for fast access
    p = [row[:] for row in times]
    total_p = [sum(job) for job in p]

    # Taillard's machine-based lower bound (for early termination check)
    def lower_bound():
        lb = 0
        for m in range(M):
            min_before = min(p[i][l] for i in range(N) for l in range(m)) if m > 0 else 0
            min_after = min(p[i][l] for i in range(N) for l in range(m+1, M)) if m < M-1 else 0
            sum_m = sum(p[i][m] for i in range(N))
            lb_m = min_before + sum_m + min_after
            if lb_m > lb:
                lb = lb_m
        return lb

    LB = lower_bound()

    # Makespan computation for a given permutation (O(N*M))
    def makespan(perm):
        t = [0] * M
        for job in perm:
            for m in range(M):
                if m == 0:
                    t[m] += p[job][m]
                else:
                    t[m] = max(t[m-1], t[m]) + p[job][m]
        return t[M-1]

    # Taillard-accelerated evaluation of all insertion positions for job x into current partial schedule
    # Returns (best_position, best_makespan)
    def taillard_insert(current, x):
        k = len(current)
        if k == 0:
            return 0, p[x][0] if M == 1 else p[x][0]  # will be computed properly below

        # Forward matrix e: completion times of current schedule
        e = [[0] * M for _ in range(k)]
        for r in range(k):
            job = current[r]
            for m in range(M):
                if m == 0:
                    e[r][m] = (e[r-1][m] if r > 0 else 0) + p[job][m]
                else:
                    e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + p[job][m]

        # Backward matrix q: tail times from position r to end
        q = [[0] * M for _ in range(k+1)]
        for r in range(k-1, -1, -1):
            job = current[r]
            for m in range(M-1, -1, -1):
                if m == M-1:
                    q[r][m] = q[r+1][m] + p[job][m]
                else:
                    q[r][m] = max(q[r+1][m], q[r][m+1]) + p[job][m]

        best_pos = 0
        best_mk = float('inf')
        # Try inserting x at each position i in [0, k]
        for i in range(k+1):
            # Compute forward vector f for job x after inserting at position i
            f = [0] * M
            if i == 0:
                prev = [0] * M
            else:
                prev = e[i-1]
            for m in range(M):
                if m == 0:
                    f[m] = prev[0] + p[x][m]
                else:
                    f[m] = max(f[m-1], prev[m]) + p[x][m]
            # Compute makespan: max over m of f[m] + q[i][m]
            mk = 0
            for m in range(M):
                val = f[m] + q[i][m]
                if val > mk:
                    mk = val
            if mk < best_mk:
                best_mk = mk
                best_pos = i
        return best_pos, best_mk

    # NEH construction with Taillard acceleration
    def neh_construct():
        # Sort jobs by total processing time descending
        order = sorted(range(N), key=lambda i: total_p[i], reverse=True)
        if N == 0:
            return []
        # Start with first job
        seq = [order[0]]
        # Insert remaining jobs
        for idx in range(1, N):
            job = order[idx]
            pos, _ = taillard_insert(seq, job)
            seq.insert(pos, job)
        return seq

    # Iterated Greedy metaheuristic
    def iterated_greedy(initial_seq, max_iters=50):
        current = initial_seq[:]
        best = current[:]
        best_mk = makespan(best)
        if best_mk == LB:
            return best

        total_processing = sum(total_p)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
        d = 3 if N > 5 else max(1, N//2)

        for _ in range(max_iters):
            # Destruction: remove d random jobs
            indices = random.sample(range(N), d)
            removed = [current[i] for i in sorted(indices, reverse=True)]
            for i in sorted(indices, reverse=True):
                del current[i]
            # Reconstruction: reinsert removed jobs one by one in random order
            random.shuffle(removed)
            for job in removed:
                pos, _ = taillard_insert(current, job)
                current.insert(pos, job)
            # Acceptance criterion
            curr_mk = makespan(current)
            if curr_mk < best_mk:
                best_mk = curr_mk
                best = current[:]
                if best_mk == LB:
                    break
            if curr_mk < makespan(best):  # current is better than best? should be caught above
                best = current[:]
                best_mk = curr_mk
            elif random.random() < math.exp(-(curr_mk - makespan(best)) / T):
                # accept worse solution
                pass
            else:
                # reject, restore to previous current (but we already modified it)
                # Instead, we keep the current as is for next iteration? Standard IG accepts or rejects the new solution.
                # Here we have already modified current to be the new solution; if we reject, we need to revert.
                # Since we don't have the old current stored, we skip revert for simplicity and accept always in this loop.
                # To strictly follow Metropolis, we would need to store old current. For speed, we use a simpler approach:
                # Always accept the new solution, but update best only if improved.
                # This is a common simplification in IG for PFSP.
                pass
        return best

    # Build initial solution
    init_seq = neh_construct()
    # Refine with Iterated Greedy
    final_seq = iterated_greedy(init_seq, max_iters=40)
    return final_seq

