        # Evaluate first two jobs
        makespan01 = _makespan_2job(times, order[0], order[1])
        makespan10 = _makespan_2job(times, order[1], order[0])
        seq = [order[0], order[1]] if makespan01 <= makespan10 else [order[1], order[0]]
        # Greedy insertion for remaining jobs
        for k in range(2, len(order)):
            job = order[k]
            best_pos = 0
            best_makespan = float('inf')
            best_idle = float('inf')
            # Forward matrix e: completion times of current seq[0..k-1]
            e = [[0] * M for _ in range(k)]
            for r in range(k):
                job_r = seq[r]
                for m in range(M):
                    if m == 0:
                        e[r][m] = (e[r-1][m] if r > 0 else 0) + times[job_r][m]
                    else:
                        e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + times[job_r][m]
            # Backward matrix q: tail times from position r to end
            q = [[0] * M for _ in range(k+1)]  # q[k][*] = 0
            for r in range(k-1, -1, -1):
                job_r = seq[r]
                for m in range(M-1, -1, -1):
                    if m == M-1:
                        q[r][m] = q[r+1][m] + times[job_r][m]
                    else:
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job_r][m]
            # Evaluate each insertion position i in [0, k]
            for i in range(k+1):
                # Forward pass for job at position i
                f = [0] * M
                prev_e = e[i-1] if i > 0 else [0] * M
                for m in range(M):
                    if m == 0:
                        f[m] = prev_e[0] + times[job][m]
                    else:
                        f[m] = max(f[m-1], prev_e[m]) + times[job][m]
                # Compute makespan
                makespan = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > makespan:
                        makespan = val
                # Tie-breaking: minimize idle time on last machine
                if makespan < best_makespan:
                    best_makespan = makespan
                    best_pos = i
                    # Compute idle time on last machine for this insertion
                    if i == 0:
                        prev_last = 0
                    else:
                        prev_last = e[i-1][M-1]
                    start_last = max(prev_last, f[M-1])
                    end_last = start_last + times[job][M-1]
                    if i == k:
                        next_first = 0
                    else:
                        next_first = q[i][M-1]
                    idle_last = max(0, next_first - end_last)
                    best_idle = idle_last
                elif makespan == best_makespan:
                    # Compute idle time on last machine for tie-breaker
                    if i == 0:
                        prev_last = 0
