def _makespan_2job(times, job1, job2):
    M = len(times[0])
    # Machine 0
    c0_0 = times[job1][0]
    c1_0 = c0_0 + times[job2][0]
    # Machine 1
    c0_1 = c0_0 + times[job1][1]
    c1_1 = max(c1_0, c0_1) + times[job2][1]
    if M == 2:
        return c1_1
    # Machine 2+
    prev2 = c0_1
    prev1 = c1_1
    for m in range(2, M):
        c0_m = prev2 + times[job1][m]
        c1_m = max(prev1, c0_m) + times[job2][m]
        prev2, prev1 = c0_m, c1_m
    return prev1

def _makespan(times, seq):
    if not seq:
        return 0
    N = len(seq)
    M = len(times[0])
    # Initialize completion times for first job
    comp = [0] * M
    for m in range(M):
        if m == 0:
            comp[m] = times[seq[0]][m]
        else:
            comp[m] = comp[m-1] + times[seq[0]][m]
    # Process remaining jobs
    for i in range(1, N):
        job = seq[i]
        for m in range(M):
            if m == 0:
                comp[m] = comp[m] + times[job][m]
            else:
                comp[m] = max(comp[m], comp[m-1]) + times[job][m]
    return comp[M-1]

