            # Swap adjacent jobs at i and i+1
            seq[i], seq[i+1] = seq[i+1], seq[i]
            new_makespan = makespan(seq)
            if new_makespan < current_makespan:
                current_makespan = new_makespan
                improved = True
                if new_makespan < best_makespan:
                    best_makespan = new_makespan
                    best_seq = seq[:]
            else:
                # Revert swap if not improving
                seq[i], seq[i+1] = seq[i+1], seq[i]
        if not improved:
            break

    return best_seq

