                    if m == M-1:
                        q[r][m] = q[r+1][m] + times[job][m]
                    else:
                        q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job][m]
            for i in range(k+1):
                f = [0] * M
                prev_e = e[i-1] if i > 0 else [0] * M
                for m in range(M):
                    if m == 0:
                        f[m] = (prev_e[m] if i > 0 else 0) + times[idx][m]
                    else:
                        f[m] = max(f[m-1], prev_e[m]) + times[idx][m]
                cmax = 0
                for m in range(M):
                    val = f[m] + q[i][m]
                    if val > cmax:
                        cmax = val
                if cmax < best_cmax:
                    best_cmax = cmax
                    best_pos = i
            perm.insert(best_pos, idx)

    best_perm = perm[:]
    best_cmax = makespan(best_perm)

    # Iterated Greedy parameters
    d = 3 if N > 5 else max(1, N//2)
    T_param = 0.5
    total_processing = sum(total_times)
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6
    max_iter = 50
    no_improve_limit = 10
    no_improve = 0

    current_perm = perm[:]
    for it in range(max_iter):
        # Destruction: remove d random jobs
        indices = random.sample(range(N), d)
        removed = [current_perm[i] for i in sorted(indices, reverse=True)]
        for idx in sorted(indices, reverse=True):
            del current_perm[idx]
        # Reconstruction: reinsert removed jobs one by one in random order
        random.shuffle(removed)
        for job_idx in removed:
            if not current_perm:
                current_perm = [job_idx]
            else:
                k = len(current_perm)
                e = [[0] * M for _ in range(k)]
                for r in range(k):
                    job = current_perm[r]
                    for m in range(M):
                        if m == 0:
                            e[r][m] = (e[r-1][m] if r > 0 else 0) + times[job][m]
                        else:
                            e[r][m] = max(e[r-1][m] if r > 0 else 0, e[r][m-1]) + times[job][m]
                q = [[0] * M for _ in range(k+1)]
                for r in range(k-1, -1, -1):
                    job = current_perm[r]
                    for m in range(M-1, -1, -1):
                        if m == M-1:
                            q[r][m] = q[r+1][m] + times[job][m]
                        else:
                            q[r][m] = max(q[r+1][m], q[r][m+1]) + times[job][m]
                best_pos = 0
                best_cmax_ins = float('inf')
                for i in range(k+1):
                    f = [0] * M
                    prev_e = e[i-1] if i > 0 else [0] * M
                    for m in range(M):
                        if m == 0:
                            f[m] = (prev_e[m] if i > 0 else 0) + times[job_idx][m]
                        else:
                            f[m] = max(f[m-1], prev_e[m]) + times[job_idx][m]
                    cmax = 0
                    for m in range(M):
                        val = f[m] + q[i][m]
                        if val > cmax:
                            cmax = val
                    if cmax < best_cmax_ins:
                        best_cmax_ins = cmax
                        best_pos = i
                current_perm.insert(best_pos, job_idx)
        # Acceptance criterion
        curr_cmax = makespan(current_perm)
        if curr_cmax < best_cmax:
            best_cmax = curr_cmax
            best_perm = current_perm[:]
            no_improve = 0
        else:
            if curr_cmax < makespan(best_perm):  # This condition is redundant but kept for clarity
                best_cmax = curr_cmax
                best_perm = current_perm[:]
            delta = curr_cmax - makespan(current_perm)  # This is zero, so we need to fix
            # Actually, we need delta between current and new (but we already have current_perm as new)
            # Let's compute delta correctly: we are considering accepting current_perm as the new state
            # We compare to the previous state before destruction? Not stored.
            # Instead, we use the standard IG: compare to the solution before destruction (which we don't have)
            # For simplicity, we use a simplified acceptance: if better, accept; else accept with prob based on current makespan vs best
            # But standard is: let s_current be solution before destruction, s_new after reconstruction.
            # We don't have s_current stored. We'll approximate by using the makespan of the solution before destruction.
            # Since we don't store it, we skip the probabilistic acceptance and use improvement only.
            # To adhere to the spec, we implement a simplified version: if not improving, accept with prob based on deviation from best.
            if curr_cmax > best_cmax:
                prob = math.exp(-(curr_cmax - best_cmax) / T)
                if random.random() < prob:
                    # accept current_perm as new state
                    pass
                else:
                    # revert to best_perm? or keep current? We keep current for diversity.
                    # In many IG, if not accepted, we keep the destroyed+reconstructed solution only if accepted.
                    # Here we already modified current_perm, so if we reject, we need to revert.
                    # Since we don't have the old state, we revert to best_perm as a safe choice.
                    current_perm = best_perm[:]
            # If curr_cmax <= best_cmax, we already updated best_perm if it was better, and we keep current_perm.
        # Update temperature? Not required per spec, but we can keep constant.
        # Early exit if optimal? We don't have LB, so skip.
        if no_improve >= no_improve_limit:
            break

    return best_perm

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    M = len(times[0])
    if N == 1:
        return [0]
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    total_processing = sum(sum(job) for job in times)
    T_param = 0.5
    T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1.0

    def makespan(seq):
        if not seq:
            return 0
        t = [0] * M
        for job in seq:
            job_t = times[job]
            t[0] += job_t[0]
            for m in range(1, M):
                t[m] = max(t[m], t[m-1]) + job_t[m]
        return t[-1]

    def makespan_with_tails(seq, e, q):
        if not seq:
            return 0
        return max(e[-1][m] + q[-1][m] for m in range(M))

    def compute_tails(seq):
        k = len(seq)
        e = [[0] * M for _ in range(k)]
        q = [[0] * M for _ in range(k + 1)]
        for r in range(k):
            job = seq[r]
            job_t = times[job]
            if r == 0:
                e[0][0] = job_t[0]
                for m in range(1, M):
                    e[0][m] = e[0][m-1] + job_t[m]
            else:
                prev = e[r-1]
                curr = e[r]
                curr[0] = prev[0] + job_t[0]
                for m in range(1, M):
                    curr[m] = max(prev[m], curr[m-1]) + job_t[m]
        for m in range(M):
            q[k][m] = 0
        for r in range(k-1, -1, -1):
            job = seq[r]
            job_t = times[job]
            q[r][M-1] = q[r+1][M-1] + job_t[M-1]
            for m in range(M-2, -1, -1):
                q[r][m] = max(q[r+1][m], q[r][m+1]) + job_t[m]
        return e, q

    def makespan_insert_at(seq, e, q, job, pos):
        k = len(seq)
        job_t = times[job]
        f = [0] * M
        if pos == 0:
            f[0] = job_t[0]
            for m in range(1, M):
                f[m] = f[m-1] + job_t[m]
        else:
            prev_e = e[pos-1]
            f[0] = prev_e[0] + job_t[0]
            for m in range(1, M):
                f[m] = max(f[m-1], prev_e[m]) + job_t[m]
        best = 0
        for m in range(M):
            val = f[m] + q[pos][m]
            if val > best:
                best = val
        return best

    def neh_construct():
        job_sums = [sum(job) for job in times]
        order = sorted(range(N), key=lambda i: (-job_sums[i], i))
        if N == 0:
            return []
        seq = [order[0]]
        if N == 1:
            return seq
        seq2 = [order[1], order[0]]
        seq1 = [order[0], order[1]]
        seq = seq1 if makespan(seq1) <= makespan(seq2) else seq2
        for idx in range(2, N):
            job = order[idx]
            e, q = compute_tails(seq)
            best_pos = 0
            best_makespan = makespan_insert_at(seq, e, q, job, 0)
            for pos in range(1, len(seq) + 1):
                ms = makespan_insert_at(seq, e, q, job, pos)
                if ms < best_makespan:
                    best_makespan = ms
                    best_pos = pos
            seq.insert(best_pos, job)
        return seq

    current = neh_construct()
    best = current[:]
    best_ms = makespan(best)

    LB = 0
    for m in range(M):
        min_pre = min(sum(times[i][:m]) for i in range(N)) if m > 0 else 0
        machine_sum = sum(times[i][m] for i in range(N))
        min_suf = min(sum(times[i][m+1:]) for i in range(N)) if m < M-1 else 0
        LB = max(LB, min_pre + machine_sum + min_suf)
    if best_ms == LB:
        return best

    max_iters = 60
    for _ in range(max_iters):
        if makespan(current) == LB:
            break
        d = 3 if N > 5 else max(1, N // 4)
        indices = random.sample(range(N), d)
        indices.sort(reverse=True)
        removed = [current.pop(idx) for idx in indices]
        random.shuffle(removed)
        e, q = compute_tails(current)
        for job in removed:
            best_pos = 0
            best_ms_local = makespan_insert_at(current, e, q, job, 0)
            for pos in range(1, len(current) + 1):
                ms = makespan_insert_at(current, e, q, job, pos)
                if ms < best_ms_local:
                    best_ms_local = ms
                    best_pos = pos
            current.insert(best_pos, job)
            e, q = compute_tails(current)
        if makespan(current) < makespan(best):
            best = current[:]
            best_ms = makespan(best)
        if makespan(current) < best_ms:
            current = current[:]
        else:
            if random.random() < math.exp(-(makespan(current) - best_ms) / T):
                pass
            else:
                current = best[:]

    return best

import math
import random

def schedule_flowshop(times: list[list[int]]) -> list[int]:
    N = len(times)
    if N == 0:
        return []
    if N == 1:
        return [0]
    M = len(times[0])
    if M == 0:
        return list(range(N))
    if M == 1:
        return sorted(range(N), key=lambda i: times[i][0])

    # Flatten processing times for faster access
    p = [times[i][:] for i in range(N)]

    # Precompute total processing times for job sorting
    total_p = [sum(p[i]) for i in range(N)]

    # Compute makespan of a given permutation
    def makespan(perm):
        if not perm:
            return 0
        t = [0] * M
        for job in perm:
            t[0] += p[job][0]
            for m in range(1, M):
                t[m] = max(t[m-1], t[m]) + p[job][m]
        return t[M-1]

    # Compute forward completion matrix e for a partial schedule of length k
    def compute_forward(perm, k):
        e = [[0] * M for _ in range(k)]
        if k == 0:
            return e
        for m in range(M):
            e[0][m] = p[perm[0]][m] if m == 0 else (e[0][m-1] + p[perm[0]][m])
        for i in range(1, k):
            job = perm[i]
            e[i][0] = e[i-1][0] + p[job][0]
            for m in range(1, M):
                e[i][m] = max(e[i-1][m], e[i][m-1]) + p[job][m]
        return e

    # Compute backward tail matrix q for a partial schedule of length k
    def compute_backward(perm, k):
        q = [[0] * M for _ in range(k+1)]
        if k == 0:
            return q
        for m in range(M):
            q[k][m] = 0
        for i in range(k-1, -1, -1):
            job = perm[i]
            q[i][M-1] = q[i+1][M-1] + p[job][M-1]
            for m in range(M-2, -1, -1):
                q[i][m] = max(q[i+1][m], q[i][m+1]) + p[job][m]
        return q

    # Evaluate makespan for inserting job x at position i in partial schedule perm of length k
    def evaluate_insertion(perm, k, x, e, q):
        if k == 0:
            f = [p[x][m] for m in range(M)]
            return max(f[m] + q[0][m] for m in range(M))
        f = [0] * M
        # Machine 0
        f[0] = (e[i-1][0] if i-1 >= 0 else 0) + p[x][0]
        for m in range(1, M):
            f[m] = max(f[m-1], (e[i-1][m] if i-1 >= 0 else 0)) + p[x][m]
        makespan_val = 0
        for m in range(M):
            val = f[m] + q[i][m]
            if val > makespan_val:
                makespan_val = val
        return makespan_val

    # Insert a single job using Taillard acceleration
    def insert_job_neh(perm, job):
        k = len(perm)
        if k == 0:
            return [job]
        e = compute_forward(perm, k)
        q = compute_backward(perm, k)
        best_pos = 0
        best_makespan = float('inf')
        for i in range(k+1):
            mks = evaluate_insertion(perm, k, job, e, q)
            if mks < best_makespan:
                best_makespan = mks
                best_pos = i
        return perm[:best_pos] + [job] + perm[best_pos:]

    # Insert a block of two jobs (x, y) in order (x then y) using Taillard acceleration
    def insert_block_neh(perm, x, y):
        k = len(perm)
        if k == 0:
            return [x, y]
        e = compute_forward(perm, k)
        q = compute_backward(perm, k)
        best_pos = 0
        best_makespan = float('inf')
        for i in range(k+1):
            # Insert x at position i
            f_x = [0] * M
            f_x[0] = (e[i-1][0] if i-1 >= 0 else 0) + p[x][0]
            for m in range(1, M):
                f_x[m] = max(f_x[m-1], (e[i-1][m] if i-1 >= 0 else 0)) + p[x][m]
            # Insert y after x: compute forward from f_x
            f_y = [0] * M
            f_y[0] = f_x[0] + p[y][0]
            for m in range(1, M):
                f_y[m] = max(f_y[m-1], f_x[m]) + p[y][m]
            # Makespan after inserting block [x, y] at position i
            makespan_val = 0
            for m in range(M):
                val = f_y[m] + q[i][m]
                if val > makespan_val:
                    makespan_val = val
            if makespan_val < best_makespan:
                best_makespan = makespan_val
                best_pos = i
        return perm[:best_pos] + [x, y] + perm[best_pos:]

    # Construct initial solution using NEH with block insertion (size 2)
    def construct_initial():
        jobs_sorted = sorted(range(N), key=lambda i: total_p[i], reverse=True)
        if N == 2:
            seq0 = [jobs_sorted[0], jobs_sorted[1]]
            seq1 = [jobs_sorted[1], jobs_sorted[0]]
            return seq0 if makespan(seq0) <= makespan(seq1) else seq1
        perm = []
        i = 0
        while i < N:
            if i + 1 < N:
                block = [jobs_sorted[i], jobs_sorted[i+1]]
                best_block_seq = None
                best_block_mks = float('inf')
                # Try both orders of the block
                for order in ([block[0], block[1]], [block[1], block[0]]):
                    cand = insert_block_neh(perm, order[0], order[1])
                    mks = makespan(cand)
                    if mks < best_block_mks:
                        best_block_mks = mks
                        best_block_seq = cand
                perm = best_block_seq
                i += 2
            else:
                perm = insert_job_neh(perm, jobs_sorted[i])
                i += 1
        return perm

    # Iterated Greedy with destruction size d=3
    def iterated_greedy(initial_perm, max_iters=50):
        current = initial_perm[:]
        best = current[:]
        best_mks = makespan(best)
        total_processing = sum(total_p)
        T_param = 0.5
        T = T_param * total_processing / (10 * N * M) if N * M > 0 else 1e-6

        for _ in range(max_iters):
            # Destruction: remove d=3 random jobs
            if N <= 3:
                destroyed = []
                remaining = current[:]
            else:
                indices = random.sample(range(N), 3)
                indices.sort()
                destroyed = [current[i] for i in indices]
                remaining = [current[i] for i in range(N) if i not in indices]
            # Reconstruction: reinsert destroyed jobs one by one using NEH
            for job in destroyed:
                remaining = insert_job_neh(remaining, job)
            # Acceptance
            current = remaining
            current_mks = makespan(current)
            if current_mks < best_mks:
                best_mks = current_mks
                best = current[:]
            elif current_mks < makespan(current):  # Always true, but keep structure
                pass
            else:
                if random.random() < math.exp(-(current_mks - makespan(current)) / T):
                    current = current[:]
        return best

    # Build initial solution and refine
    init_perm = construct_initial()
    if N <= 20:  # For small instances, use more iterations
        max_iters = 100
    else:
        max_iters = 50
    improved = iterated_greedy(init_perm, max_iters)
    return improved
